let calculatorState={expression:'',result:null,error:'',scientific:false,angle:'deg',memory:0,finished:false};
function calculatorNumber(value){if(value==null)return '0';return Math.abs(value)>=1e12||(value!==0&&Math.abs(value)<1e-7)?value.toExponential(8).replace('.',','):value.toLocaleString('pt-BR',{maximumSignificantDigits:12});}
function paintCalculator(){const c=calculatorState,keys=[['AC','clear'],['⌫','erase'],['%','%'],['÷','/'],['7','7'],['8','8'],['9','9'],['×','*'],['4','4'],['5','5'],['6','6'],['−','-'],['1','1'],['2','2'],['3','3'],['+','+'],['±','sign'],['0','0'],[',','.'],['=','equals']],science=[['sin','sin('],['cos','cos('],['tan','tan('],['π','pi'],['e','e'],['asin','asin('],['acos','acos('],['atan','atan('],['ln','ln('],['log','log('],['√','sqrt('],['x²','^2'],['xʸ','^'],['x!','!'],['1/x','reciprocal'],['(','('],[')',')'],['|x|','abs('],['eˣ','exp('],['Graus/Rad','angle']];openModal('Calculadora','<div class="calculator-mode"><span>'+ (c.scientific?'Científica · '+(c.angle==='deg'?'Graus':'Radianos'):'Básica')+'</span>'+btn('calculator-scientific',icon('scientific')+'<span class="sr-only">Alternar calculadora científica</span>','round')+'</div><label class="sr-only" for="calculator-expression">Expressão matemática</label><input id="calculator-expression" class="calculator-display" readonly value="'+escape(c.expression.replace(/\*/g,'×').replace(/\//g,'÷').replace(/\./g,','))+'" placeholder="0"><output class="calculator-result tabular" aria-live="polite">'+escape(c.error||calculatorNumber(c.result))+'</output><div class="calculator-memory">'+[['MC','clear'],['MR','recall'],['M+','add'],['M−','subtract']].map(([label,op])=>btn('calculator-memory',label,'choice',{op})).join('')+'</div>'+(c.scientific?'<div class="calculator-science">'+science.map(([label,token])=>btn('calculator-key',label,'calculator-key',{token})).join(''):'')+'<div class="calculator-keypad">'+keys.map(([label,token])=>btn('calculator-key',label,'calculator-key'+(token==='equals'?' selected':''),{token})).join('')+'</div><p class="small muted calculator-help">Percentual: 10% = 0,1. '+(c.memory?'Memória: '+calculatorNumber(c.memory)+'.':'')+'</p>','calculator',null,btn('close-modal','Voltar','choice'));}
function calculatorKey(token){const c=calculatorState;c.error='';try{if(token==='clear'){c.expression='';c.result=null;c.finished=false;}else if(token==='erase'){c.expression=c.expression.slice(0,-1);c.finished=false;}else if(token==='angle')c.angle=c.angle==='deg'?'rad':'deg';else if(['equals','sign','reciprocal'].includes(token)){const answer=calculateExpression(c.expression,c.angle);c.result=token==='sign'?-answer:token==='reciprocal'?(answer===0?calculateExpression('1/0',c.angle):1/answer):answer;if(token!=='equals')c.expression=String(c.result);c.finished=true;}else{if(c.finished){c.expression=/^[+\-*/^!%]/.test(token)?'('+String(c.result)+')':'';c.finished=false;}if(c.expression.length+token.length<=300)c.expression+=token;}if(token!=='equals'&&!c.finished){try{c.result=c.expression?calculateExpression(c.expression,c.angle):null;}catch(e){c.result=null;}}}catch(e){c.error=e.message;c.finished=false;}paintCalculator();}
