 if(!productForm.editId){const samples={'Cafés':'café','Hortifruti-Granjeiro':'banana','Piscicultura':'tilápia','Laticínios':'queijo','Charcutaria':'salame','Doces':'goiabada','Bebidas':'suco','Bolos':'Bolo','Panificação':'Pão','Grãos':'Arroz','Artesanato':'Vaso de barro','Beleza':'Sabonete natural','Mel e apícolas':'mel','Conservas e temperos':'geleia'};const old=productForm.variants[0],suggestion=E.classify(samples[category]||'');productForm.variants=[newVariant(suggestion)];productForm.variants[0].stockInput=old.stockInput;autoValues(0);}
