function options(values,current,action,index){return'<div class="choices'+(action==='coffee-type'?' coffee':'')+'">'+values.map(v=>btn(action,escape(typeof v==='number'?(v===1000?'1 kg':v+' g'):v),'choice'+(v===current?' selected':''),{value:v,index:index})).join('')+'</div>';}
function productPresentationPanels(){
 const f=productForm,isCoffee=f.category==='Cafés';
 let body=f.variants.map((v,index)=>{const per=E.unitLabel(v.unit,1),nameLabel=isCoffee?'Tipo de Café':'Unidade de Venda';let format='<section class="panel">'+(f.variants.length>1?'<div class="variant-head"><h2>Opção de venda '+(index+1)+'</h2>'+btn('remove-variant',icon('trash'),'red',{index})+'</div>':'')+'<h2>Configurações do Produto</h2>';
 format+=registrationDimensions(v,index,isCoffee);
 if(v.unit==='Caixa')format+='<div class="two" style="margin-top:15px">'+field('content-'+index,'Conteúdo da caixa',v.contentCount||'','data-variant="'+index+'" data-field="contentCount" inputmode="numeric" placeholder="Ex.: 12"')+'<div class="form-field"><label for="content-unit-'+index+'">Unidade do conteúdo</label><select id="content-unit-'+index+'" data-variant="'+index+'" data-field="contentUnit">'+['unidades','dúzias','pacotes','kg'].map(u=>'<option'+(v.contentUnit===u?' selected':'')+'>'+u+'</option>').join('')+'</select></div></div>';

 if(v.unit==='Vidro'&&!v.volume)format+='<div style="margin-top:14px">'+field('volume-'+index,'Volume do vidro (ml)',v.volume||'','data-variant="'+index+'" data-field="volume" inputmode="numeric" placeholder="Ex.: 500"')+'</div>';
 format+='</section><section class="panel values-stock-panel"><h2>Valores e Estoque</h2><div class="two">'+field('price-'+index,'Preço por '+per,v.priceInput,'data-variant="'+index+'" data-field="priceInput" inputmode="decimal"')+field('cost-'+index,'Custo por '+per,v.costInput,'data-variant="'+index+'" data-field="costInput" inputmode="decimal"')+'</div><div class="two">'+field('initial-'+index,f.editId?'Saldo atual ('+E.unitLabel(v.unit,2)+')':'Estoque Inicial ('+E.unitLabel(v.unit,2)+')',v.stockInput,'data-variant="'+index+'" data-field="stockInput" inputmode="'+(['kg','Litro'].includes(v.unit)?'decimal':'numeric')+'"'+(f.editId?' readonly':''))+field('minimum-'+index,'Estoque Mínimo',v.minInput,'data-variant="'+index+'" data-field="minInput" inputmode="'+(['kg','Litro'].includes(v.unit)?'decimal':'numeric')+'"')+'</div><p class="form-help">Valores editáveis por opção de venda.</p><div class="notice" id="stock-notice-'+index+'">'+icon('box')+' '+(f.editId?'O saldo muda somente em movimentações.':'Ao salvar: entrada inicial de '+escape(v.stockInput||0)+' '+E.unitLabel(v.unit,E.number(v.stockInput))+'.')+'</div></section>';return format;}).join('');
 return body;
}
