function saveActiveDiscount(){if(!draft||draft.discountScope!=='item')return;const item=draft.items[draft.active];if(item){item.discountMode=draft.discountMode||'R$';item.discountValue=draft.discountValue||'';}}
function loadActiveDiscount(){if(!draft||draft.discountScope!=='item')return;const item=draft.items[draft.active];draft.discountMode=item?.discountMode||'R$';draft.discountValue=item?.discountValue||'';}
function selectDiscountItem(index){if(!draft||!draft.items[index])return;saveActiveDiscount();draft.active=index;loadActiveDiscount();}
function appliedDiscountLabel(amount){return (amount>0?'<span class="discount-applied-dot" aria-hidden="true"></span>':'')+'Desconto '+E.money(Number.isFinite(amount)?amount:0);}
function exactItemNet(s){return s.items.every(i=>Number.isFinite(i.netTotal)&&i.netTotal>=0)&&s.items.reduce((n,i)=>n+i.netTotal,0)===s.total;}

function createDraft(id){numericTouched.delete('sale-quantity');if(draft)saveActiveDiscount();if(!draft)draft={scope,items:[],active:0,payment:'Pix',split:false,parts:[],partsManual:false,clientName:'',clientId:null,uf:'',city:'',neighborhood:'',clientExpanded:false,statesExpanded:false,discountScope:'item',discountMode:'R$',discountValue:''};const found=draft.items.findIndex(i=>i.productId===id);if(found>=0)draft.active=found;else{draft.items.push({productId:id,rawQty:'0',discountMode:'R$',discountValue:''});draft.active=draft.items.length-1;}loadActiveDiscount();splitUpdate();page='Venda';render();window.scrollTo(0,0);}
function splitUpdate(){if(draft&&draft.split&&!draft.partsManual){const total=Math.max(0,model.quote(draft).total);draft.parts=[{method:draft.parts[0]&&draft.parts[0].method||'Pix',value:cashInput(Math.floor(total/2))},{method:draft.parts[1]&&draft.parts[1].method||'Dinheiro',value:cashInput(total-Math.floor(total/2))}];}}
function saleError(includePayment=true){if(!draft)return'';const quote=model.quote(draft);for(const i of quote.items){const p=model.product(i.productId);if(!Number.isFinite(i.qty)||i.qty<=0)return'Informe a quantidade dos produtos.';if(!['kg','Litro'].includes(p.unit)&&!Number.isInteger(i.qty))return'Use uma quantidade inteira para '+p.name+'.';if(i.qty>p.stock)return'Estoque insuficiente: há '+E.quantity(p.stock)+' '+E.unitLabel(p.unit,p.stock)+' de '+p.name+'.';}if(draft.discountScope==='item'&&quote.items.some(i=>!i.discountValid))return'O desconto de cada produto deve ser válido e não superar seu valor.';if(!Number.isFinite(quote.discount)||quote.discount<0||quote.discount>=quote.subtotal)return'O desconto deve ser válido e menor que o subtotal.';if(includePayment&&draft.split&&(draft.parts.some(p=>!E.PAYMENTS.includes(p.method)||!Number.isFinite(E.cents(p.value))||E.cents(p.value)<=0)||draft.parts.reduce((s,p)=>s+E.cents(p.value),0)!==quote.total))return'A soma dos pagamentos deve ser igual ao total.';return'';}

function saleFamily(p){
 const n=E.normalize(p.baseName||p.name);
 return model.data.products.filter(x=>x.category===p.category&&(p.category==='Hortifruti-Granjeiro'&&/^banana\b/.test(n)?/^banana\b/.test(E.normalize(x.baseName||x.name)):E.normalize(x.baseName||x.name)===n));
}
function saleVariety(p){return titleName((p.baseName||p.name).replace(/^banana\s*/i,'')||'Banana');}

