function chooseSaleOption(field,value){
 const p=model.product(draft.items[draft.active].productId),order=['type','variety','format','unit','weight'],position=order.indexOf(field),matches=saleFamily(p).filter(v=>(field==='variety'?saleVariety(v)===value:String(v[field])===String(value))&&order.slice(0,position).every(k=>k==='variety'?saleVariety(v)===saleVariety(p):String(v[k]||'')===String(p[k]||'')));
 const fields=['type','format','unit','weight'];matches.sort((a,b)=>fields.reduce((n,k)=>n+(String(b[k])===String(p[k])?1:0)-(String(a[k])===String(p[k])?1:0),0));
 if(matches[0])selectSaleWeight(matches[0].id);
}
function stockWarning(p){openModal('Aviso','<div class="stock-alert"><div class="stock-alert-symbol" aria-hidden="true">⚠️</div><p>Você tem apenas <strong>'+E.quantity(p.stock)+' '+E.unitLabel(p.unit,p.stock)+'</strong> de '+escape(titleName(p.name))+' em estoque.</p>'+btn('close-modal','OK','success')+'</div>','stock-warning');}
