function exportCSV(name,rows){const encode=v=>{let s=String(v==null?'':v);if(/^[=+@-]/.test(s))s="'"+s;return'"'+s.replace(/"/g,'""')+'"';};download(name,'\ufeff'+rows.map(row=>row.map(encode).join(';')).join('\r\n'),'text/csv;charset=utf-8');toast('Relatório exportado.');}
function download(name,content,type){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}

function shiftDay(day,delta){const date=new Date(day+'T12:00:00Z');date.setUTCDate(date.getUTCDate()+delta);return date.toISOString().slice(0,10);}
function monday(day){const d=new Date(day+'T12:00:00Z');return shiftDay(day,-((d.getUTCDay()+6)%7));}
function weekData(){
 const end=shiftDay(weekStart,7),n=E.normalize(weekQuery);
 const sales=model.data.sales.filter(s=>s.scope===scope&&E.dayKey(s.date)>=weekStart&&E.dayKey(s.date)<end&&(!n||E.normalize(s.items.map(i=>i.name+' '+i.description).join(' ')+' '+E.money(s.total)+' '+s.payments.map(p=>p.method).join(' ')).includes(n)));
 const completed=sales.filter(s=>s.status==='completed');return{sales,total:completed.reduce((n,s)=>n+s.total,0),count:completed.length};
}

function weeklyPage(){
 const data=weekData(),format=day=>new Date(day+'T12:00:00Z').toLocaleDateString('pt-BR',{day:'2-digit',month:'short'}),weekEnd=shiftDay(weekStart,6),days=Array.from({length:7},(_,i)=>shiftDay(weekStart,i));
 const head=header('Vendas','weekly-back').replace('<span class="spacer"></span>',btn('weekly-search',icon('search'),'title-search'));
 const daily=day=>data.sales.filter(s=>E.dayKey(s.date)===day).sort((a,b)=>new Date(b.date)-new Date(a.date));
 const dayCard=day=>{
  const sales=daily(day),completed=sales.filter(s=>s.status==='completed'),total=completed.reduce((n,s)=>n+s.total,0),open=weekDaysOpen.has(day)||!!weekQuery,label=new Date(day+'T12:00:00Z').toLocaleDateString('pt-BR',{weekday:'long',day:'2-digit',month:'long'});
  return'<section class="week-day">'+btn('week-day','<span><strong>'+escape(label)+'</strong><small>'+grammarCount(completed.length,'venda','vendas')+'</small></span><span class="tabular">'+E.money(total)+' '+icon(open?'down':'chevron')+'</span>','week-day-heading',{day})+(open?'<div class="week-sales">'+(sales.length?sales.map(s=>btn('sale-detail','<span><strong>'+escape(s.items.map(i=>E.quantity(i.qty)+'× '+titleName(i.name)+' '+i.description).join(' · '))+'</strong><small>'+new Date(s.date).toLocaleTimeString('pt-BR',{timeZone:'America/Sao_Paulo',hour:'2-digit',minute:'2-digit'})+' · '+s.payments.map(p=>p.method).join(' + ')+(s.status==='returned'?' · Devolvida':'')+'</small></span><span class="week-sale-total">'+E.money(s.total)+' '+icon('chevron')+'</span>','list-row',{id:s.id})).join(''):'<p class="week-day-empty">Nenhuma venda neste dia.</p>')+'</div>':'')+'</section>';
 };
 const empty=days.filter(day=>!daily(day).length),withSales=days.filter(day=>daily(day).length),emptyGroup=empty.length?'<section class="empty-days">'+btn('week-empty-days','<span><strong>Dias sem vendas</strong><small>'+empty.length+' '+(empty.length===1?'dia':'dias')+' nesta semana</small></span><span class="tabular">R$ 0,00 '+icon(emptyDaysOpen?'down':'chevron')+'</span>','week-day-heading empty-days-heading')+(emptyDaysOpen?'<div class="empty-days-list">'+empty.map(dayCard).join('')+'</div>':'')+'</section>':'';
 return'<div class="subview">'+head+'<div class="week-switch">'+btn('week-shift',icon('back'),'round blue',{delta:-1})+'<span class="week-range">'+format(weekStart)+' — '+format(weekEnd)+'</span>'+btn('week-shift',icon('chevron'),'round blue',{delta:1})+'</div><div class="chips">'+btn('week-scope','Loja','chip'+(scope==='loja'?' selected':''),{scope:'loja'})+model.data.events.map(e=>btn('week-scope',escape(e.name),'chip'+(scope===e.id?' selected':''),{scope:e.id})).join('')+'</div>'+(weekSearchOpen?'<div class="search">'+icon('search')+'<input id="week-search" aria-label="Buscar venda" placeholder="Buscar venda" value="'+escape(weekQuery)+'"></div>':'')+'<section class="week-summary"><span class="muted">Vendas da semana · '+escape(scopeName(scope))+'</span><div class="week-total tabular">'+E.money(data.total)+'</div><p class="small muted">'+grammarCount(data.count,'venda concluída','vendas concluídas')+'</p></section>'+emptyGroup+withSales.map(dayCard).join('')+'</div>';
}
