function calendarEscape(value){return String(value||'').replace(/\\/g,'\\\\').replace(/\r?\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');}
function foldCalendarLine(line){let result='',length=0;for(const char of line){const bytes=unescape(encodeURIComponent(char)).length;if(length+bytes>75){result+='\r\n ';length=1;}result+=char;length+=bytes;}return result;}
