// Gestão: métricas financeiras primeiro, filtros diretos e assuntos independentes.
const managementExpanded=new Set();
function dateBR(value){if(value==null||value==='')return 'Data não informada';const literal=String(value),day=/^\d{4}-\d{2}-\d{2}$/.test(literal)?literal:Number.isFinite(Date.parse(value))?E.dayKey(value):'';return /^\d{4}-\d{2}-\d{2}$/.test(day)?day.slice(8,10)+'/'+day.slice(5,7)+'/'+day.slice(0,4):'Data não informada';}
function monthBR(value,withYear){return new Date(value+'-15T12:00:00Z').toLocaleDateString('pt-BR',{month:'long',...(withYear?{year:'numeric'}:{}),timeZone:'America/Sao_Paulo'}).replace(/^./,c=>c.toUpperCase());}
function salesContext(){const e=eventChoice();return e&&E.eventSellingNow(e,Date.now())?'<p class="products-context"><i class="active-event-dot" aria-hidden="true"></i><span>Evento ativo: '+escape(managementEventName(e))+'</span></p>':'<p class="products-context">Área de Vendas</p>';}
function managementSection(key,title,preview,body){return '<details class="panel management-section" data-management-section="'+key+'"'+(managementExpanded.has(key)?' open':'')+'><summary><span><strong>'+title+'</strong><small>'+escape(preview)+'</small></span>'+icon('down')+'</summary><div class="management-section-body">'+body+'</div></details>';}
function kpiRow(k,index){return '<details class="kpi-item" data-kpi="'+k.key+'"><summary><span>'+index+'. '+escape(k.title)+'</span><strong class="tabular">'+k.value+'</strong></summary><p>'+escape(k.formula)+'</p></details>';}
// As quantidades preservam a unidade de cada apresentação; peso não é somado a pacotes.
function quantityBreakdown(items){const units=new Map();items.forEach(i=>{if(Number.isFinite(i.qty)&&i.qty>0)units.set(i.unit,(units.get(i.unit)||0)+i.qty);});return [...units].map(([unit,qty])=>({unit,qty:Math.round(qty*1000)/1000})).sort((a,b)=>a.unit.localeCompare(b.unit,'pt-BR'));}
function quantityHeadline(items){const groups=quantityBreakdown(items),discrete=groups.filter(g=>!['kg','Litro'].includes(g.unit)).reduce((n,g)=>n+g.qty,0),parts=[];if(discrete)parts.push(E.quantity(discrete)+' '+(discrete===1?'unidade de venda':'unidades de venda'));groups.filter(g=>['kg','Litro'].includes(g.unit)).forEach(g=>parts.push(E.quantity(g.qty)+' '+E.unitLabel(g.unit,g.qty)));return parts.join(' · ')||'0';}
function quantityRows(items){const groups=quantityBreakdown(items);return groups.length?groups.map(g=>'<div class="management-value-row"><span>'+escape(E.unitLabel(g.unit,2))+'</span><strong>'+E.quantity(g.qty)+'</strong></div>').join(''):'<p class="small muted">Nenhuma quantidade registrada.</p>';}
function eventLoad(id){return (model.data.eventLoads||[]).find(x=>x.eventId===id)||null;}
function eventSoldQuantities(id){const sums=new Map();model.data.sales.filter(s=>s.status==='completed'&&s.scope===id).forEach(s=>s.items.forEach(i=>{const key=i.productId+'|'+i.unit,previous=sums.get(key)||{productId:i.productId,name:i.name,description:i.description,unit:i.unit,qty:0};previous.qty+=i.qty;sums.set(key,previous);}));return [...sums.values()].map(x=>({...x,qty:Math.round(x.qty*1000)/1000}));}
function eventLoadBalance(id){const load=eventLoad(id);if(!load)return null;const sold=eventSoldQuantities(id),losses=model.data.movements.filter(m=>m.kind==='loss'&&m.eventId===id),deduct=i=>(sold.find(v=>v.productId===i.productId&&v.unit===i.unit)?.qty||0)+losses.filter(m=>m.productId===i.productId&&m.unit===i.unit).reduce((n,m)=>n+m.qty,0),balance=load.items.map(i=>({...i,qty:Math.round((i.qty-deduct(i))*1000)/1000})),missing=[...sold,...losses.map(m=>({productId:m.productId,unit:m.unit,qty:m.qty}))].filter(i=>!load.items.some(l=>l.productId===i.productId&&l.unit===i.unit)||deduct(i)>(load.items.find(l=>l.productId===i.productId&&l.unit===i.unit)?.qty||0));return {load,sold,losses,balance,missing};}
function productMetrics(sel,m){const sold=m.sales.flatMap(s=>s.items);return '<div class="product-primary-metrics"><details class="product-metric" data-product-metric="sold"><summary><span>Produtos vendidos</span><strong class="tabular">'+escape(quantityHeadline(sold))+'</strong>'+icon('down')+'</summary><p class="product-metric-note">Vendas concluídas na origem e no período selecionados; devoluções excluídas.</p><div class="product-metric-body">'+quantityRows(sold)+'</div></details></div>';}
let eventLoadDraft=null;
function eventLoadProducts(id){const load=eventLoad(id),products=model.data.products.map(p=>({productId:p.id,name:p.name,description:E.description(p),unit:p.unit}));[...(load?.items||[]),...eventSoldQuantities(id)].forEach(i=>{if(!products.some(p=>p.productId===i.productId&&p.unit===i.unit))products.push({productId:i.productId,name:i.name,description:i.description,unit:i.unit});});return products;}
function startEventLoad(id){const events=model.data.events.slice().sort((a,b)=>b.start.localeCompare(a.start)),chosen=events.find(e=>e.id===id)||events.find(e=>e.status==='active')||events[0];if(!chosen)return toast('Crie um evento para registrar os produtos levados.');const load=eventLoad(chosen.id);eventLoadDraft={eventId:chosen.id,products:eventLoadProducts(chosen.id).map(p=>({...p,raw:load?(load.items.find(i=>i.productId===p.productId&&i.unit===p.unit)?.qty??''):'',fromRecord:!!load}))};paintEventLoad();}
function paintEventLoad(){if(!eventLoadDraft)return;const d=eventLoadDraft,events=model.data.events.slice().sort((a,b)=>b.start.localeCompare(a.start));openModal('Produtos levados para o evento','<label for="event-load-event">Evento</label><select id="event-load-event">'+events.map(e=>'<option value="'+escape(e.id)+'"'+(e.id===d.eventId?' selected':'')+'>'+escape(managementEventName(e)+' · '+dateBR(e.start))+'</option>').join('')+'</select><p class="dialog-text event-load-help">Informe o total que foi levado, incluindo reposições. Campos vazios contam como zero. Este registro acompanha a feira e mantém o saldo do estoque geral.</p><div class="event-load-list">'+d.products.map((p,index)=>'<div class="event-load-row"><span><strong>'+escape(titleName(p.name))+'</strong><small>'+escape(p.description)+' · '+escape(E.unitLabel(p.unit,2))+'</small></span><label class="sr-only" for="event-load-'+index+'">Quantidade levada de '+escape(p.name+' '+p.description)+'</label><input id="event-load-'+index+'" data-event-load-index="'+index+'" inputmode="'+(['kg','Litro'].includes(p.unit)?'decimal':'numeric')+'" value="'+escape(p.raw)+'" placeholder="Quantidade"></div>').join('')+'</div><div id="event-load-error" class="sr-only" role="status"></div>'+btn('save-event-load','Salvar quantidades','success modal-action')+btn('close-modal','Voltar','choice modal-action'),'event-load',{id:d.eventId});}
function captureEventLoad(){if(!eventLoadDraft)return;eventLoadDraft.products.forEach((p,index)=>{const el=document.getElementById('event-load-'+index);if(el)p.raw=el.value;});}
function validateEventLoads(data){if(data.eventLoads==null)return;if(!Array.isArray(data.eventLoads)||new Set(data.eventLoads.map(x=>x&&x.eventId)).size!==data.eventLoads.length||data.eventLoads.some(x=>!x||typeof x.eventId!=='string'||!Array.isArray(x.items)||new Set(x.items.map(i=>i&&i.productId+'|'+i.unit)).size!==x.items.length||x.items.some(i=>!i||typeof i.productId!=='string'||typeof i.unit!=='string'||!Number.isFinite(i.qty)||i.qty<0||(!['kg','Litro'].includes(i.unit)&&!Number.isInteger(i.qty)))))throw Error('Registro de produtos levados inválido.');}
function saveEventLoad(){if(!eventLoadDraft)return;captureEventLoad();const d=eventLoadDraft,items=[];let message='';for(const p of d.products){const value=String(p.raw).trim(),qty=value===''?0:E.number(value);if((value!==''&&!/^\d+(?:[.,]\d{1,3})?$/.test(value))||!Number.isFinite(qty)||qty<0||(!['kg','Litro'].includes(p.unit)&&!Number.isInteger(qty))||Math.abs(qty*1000-Math.round(qty*1000))>1e-6){message='Informe uma quantidade válida de '+p.name+'. Use até três casas decimais para kg e litros.';break;}if(qty>0)items.push({productId:p.productId,name:p.name,description:p.description,unit:p.unit,qty});}if(!message){const shortfall=eventSoldQuantities(d.eventId).find(s=>s.qty>(items.find(i=>i.productId===s.productId&&i.unit===s.unit)?.qty||0));if(shortfall)message='O total levado de '+shortfall.name+' deve cobrir as '+E.quantity(shortfall.qty)+' '+E.unitLabel(shortfall.unit,shortfall.qty)+' já vendidas nessa feira.';}if(message){const el=document.getElementById('event-load-error');el.textContent=message;el.className='error';return;}const before=model.data.eventLoads||[],stamp=new Date().toISOString(),old=eventLoad(d.eventId),record={eventId:d.eventId,createdAt:old?.createdAt||stamp,updatedAt:stamp,items};model.data.eventLoads=[...before.filter(x=>x.eventId!==d.eventId),record];if(!persist()){model.data.eventLoads=before;return toast('Não foi possível salvar as quantidades. Exporte um backup.');}const e=model.data.events.find(x=>x.id===d.eventId);managementScope=d.eventId;if(e&&(month<e.start.slice(0,7)||month>e.end.slice(0,7)))month=e.start.slice(0,7);managementDays.clear();managementHours={from:'',until:''};closeModal();render();toast('Produtos levados registrados.');}

function managementMetrics(sel,m){const kpis=kpiData(sel);const finances='<div class="management-financial-body"><div class="principal-kpis">'+kpis.slice(0,3).map((k,i)=>kpiRow(k,i+1)).join('')+'</div><div class="management-sales-summary">'+btn('period-sales','<strong>'+m.sales.length+'</strong><span>Vendas</span>','management-small-stat')+'<div class="management-small-stat"><strong class="tabular">'+(m.sales.length?E.money(m.ticket):'—')+'</strong><span>Ticket médio</span></div></div>'+managementSection('other-metrics','Outras métricas','Indicadores das vendas e dos clientes','<div class="kpi-grid">'+kpis.slice(3).map((k,i)=>kpiRow(k,i+4)).join('')+'</div><div class="two">'+btn('log-approaches','Registrar abordagens','choice')+btn('expense','Registrar despesa','choice')+'</div>'+metricSources())+'</div>';return '<section class="panel management-primary" aria-labelledby="management-metrics-title"><h2 id="management-metrics-title">Métricas</h2><p class="management-period">'+escape(periodText(sel))+'<br>'+escape(reportScopeName(sel.scope))+'</p>'+productMetrics(sel,m)+managementSection('financial-metrics','Métricas financeiras',E.money(m.revenue)+' de receita líquida',finances)+'</section>';}

function metricSources(){return '<details class="research-sources"><summary>Como calculamos e fontes</summary><p>Os valores usam os registros do app. Indicadores sem informação suficiente mostram —. Toque em uma métrica para consultar sua fórmula.</p><a href="https://www.sebraeplay.com.br/content/estrategias-comerciais-para-o-sucesso-do-varejo" target="_blank" rel="noopener">Sebrae · indicadores do varejo</a><a href="https://www.shopify.com/br/blog/indicadores-kpi-ecommerce" target="_blank" rel="noopener">Shopify · indicadores comerciais</a></details>';}
function managementMonths(sel,events){const recent=recentMonths(),months=[...new Set([...recent,month,...model.data.sales.map(s=>E.monthKey(s.date)),...events.map(e=>e.start.slice(0,7))])].sort().reverse();const row=(value,label)=>'<div class="management-month-row'+(month===value?' selected':'')+'">'+btn('select-month','<span>'+escape(label)+'</span>'+icon(month===value?'check':'chevron'),'month-select',{month:value})+btn('month-calendar',icon('calendar'),'month-calendar',{month:value})+'</div>';return '<section class="panel months-section"><h2>Meses</h2><div class="management-month-list">'+recent.map(value=>row(value,monthBR(value,false))).join('')+'<div class="management-month-row all-months-row">'+btn('all-months','<span>Todos os meses</span>'+icon(allMonthsOpen?'down':'chevron'),'month-select')+btn('month-calendar',icon('calendar'),'month-calendar',{month:'all'})+'</div></div>'+'<p class="management-period small">'+escape(periodText(sel))+'</p>'+btn('calendar-toggle','<span>'+icon('calendar')+' Escolher dias e horários</span>'+icon(calendarOpen?'down':'chevron'),'calendar-shortcut')+(calendarOpen?calendarSection():'')+'</section>';}
function managementResults(m){const line=(key,name,amount,note)=>btn('metric','<span>'+name+(note?'<small>'+escape(note)+'</small>':'')+'</span><strong class="tabular">'+(key==='cost'||key==='expense'?'− ':'')+E.money(amount)+'</strong>','management-value-row'+(key==='result'?' result-value'+(amount<0?' negative':''):''),{key});return managementSection('result','Resultado',E.money(m.result)+' · após custos e despesas',line('revenue','Receita líquida',m.revenue)+line('cost','Custo dos produtos',m.cost)+line('gross','Lucro bruto',m.gross,'Margem '+(m.margin==null?'—':m.margin.toLocaleString('pt-BR',{maximumFractionDigits:1})+'%'))+line('expense','Despesas',m.expense)+line('result','Resultado',m.result)+btn('expense','Registrar despesa','choice management-wide-action'));}
function managementRank(m){const maximum=m.rank[0]?.amount||0,body=m.rank.length?m.rank.map(r=>btn('rank-detail','<span class="management-ranking-label"><span><strong>'+escape(titleName(r.name))+'</strong><small>'+escape(r.description||'')+' · '+E.quantity(r.qty)+' '+E.unitLabel(r.unit,r.qty)+'</small></span><strong class="tabular">'+E.money(r.amount)+'</strong></span><span class="track"><span class="bar" style="width:'+(maximum?r.amount/maximum*100:0)+'%"></span></span>','management-rank-row',{id:r.id})).join(''):'<p class="muted">Sem produtos vendidos neste recorte.</p>';return managementSection('best-sellers','Mais vendidos',m.rank.length?titleName(m.rank[0].name)+' · '+E.money(m.rank[0].amount):'Sem vendas no período',body);}
function managementPeak(m){const counts=new Map();m.sales.forEach(s=>{const h=Number(brTime(s.date).slice(0,2));counts.set(h,(counts.get(h)||0)+1);});const ranked=[...counts].sort((a,b)=>b[1]-a[1]||a[0]-b[0]),peak=ranked.length?ranked.filter(x=>x[1]===ranked[0][1]):[];return {counts:[...counts].sort((a,b)=>a[0]-b[0]),hours:peak.map(([h])=>String(h).padStart(2,'0')+'h às '+String(h+1).padStart(2,'0')+'h'),count:ranked[0]?.[1]||0};}
function managementPayments(m){const methods=Object.entries(m.payments).sort((a,b)=>b[1]-a[1]),peak=managementPeak(m),fmt=n=>n.toLocaleString('pt-BR',{maximumFractionDigits:1})+'%',preview=methods.length?methods[0][0]+' · '+fmt(m.revenue?methods[0][1]/m.revenue*100:0)+' · Pico '+(peak.hours[0]||'—'):'Sem pagamentos no período';return managementSection('payments','Pagamentos',preview,(methods.length?methods.map(([method,amount])=>btn('payment-detail','<span class="management-ranking-label"><span>'+escape(method)+'</span><strong class="tabular">'+fmt(m.revenue?amount/m.revenue*100:0)+' · '+E.money(amount)+'</strong></span><span class="track"><span class="bar payment-bar" style="width:'+(m.revenue?amount/m.revenue*100:0)+'%"></span></span>','management-rank-row',{method})).join(''):'<p class="muted">Sem pagamentos neste recorte.</p>')+'<div class="management-peak"><strong>Horário de pico</strong><span>'+escape(peak.hours.length?peak.hours.join(' / '):'—')+'</span><small>Brasília · '+(peak.count?peak.count+' '+(peak.count===1?'venda':'vendas')+' por janela de uma hora'+(peak.hours.length>1?' · empate':''):'Sem vendas registradas')+'</small></div>');}
function managementRevenue(m){const days=Object.entries(m.daily).sort((a,b)=>a[0].localeCompare(b[0])),max=Math.max(1,...days.map(x=>x[1]));return managementSection('daily-revenue','Receita por dia',days.length+' '+(days.length===1?'dia com vendas':'dias com vendas'),days.length?days.map(([day,amount])=>btn('selected-day-sales','<span class="management-ranking-label"><span>'+dateBR(day)+'</span><strong class="tabular">'+E.money(amount)+'</strong></span><span class="track"><span class="bar" style="width:'+amount/max*100+'%"></span></span>','management-rank-row',{day})).join(''):'<p class="muted">Sem vendas no período.</p>');}
function managementReports(events,sel,m){events=events.filter(e=>['all','events'].includes(sel.scope)||e.id===sel.scope);return managementSection('reports','Relatórios','CSV de feiras e meses · Vendas e clientes','<div class="management-report-links">'+[['products','box','Produtos'],['clients','users','Clientes'],['events','calendar','Eventos']].map(([kind,ico,name])=>btn('management-report','<span>'+icon(ico)+' '+name+'</span>'+icon('chevron'),'link-row',{kind})).join('')+'</div><h3>Relatórios CSV</h3><p class="small muted">Cada feira reúne todos os seus dias. Os arquivos mensais reúnem as vendas individuais.</p><div class="fair-csv-list">'+events.map(e=>'<div class="report-event-row"><span><strong>'+escape(managementEventName(e))+'</strong><small>'+dateBR(e.start)+(e.end!==e.start?' a '+dateBR(e.end):'')+' · '+(e.status==='active'?'Atual / programada':'Encerrada')+'</small></span>'+btn('export-fair',icon('download')+' CSV','choice',{id:e.id})+'</div>').join('')+'</div>'+(['all','loja'].includes(sel.scope)?btn('export-monthly','<span>Vendas fora dos eventos<small>'+monthBR(month,true)+'</small></span>'+icon('download'),'link-row'):'')+btn('export-sales','<span>Vendas do período selecionado<small>'+escape(periodText(sel))+'</small></span>'+icon('download'),'link-row')+btn('management-data','<span>Dados gerais e backup<small>Todos os registros da feira e do negócio</small></span>'+icon('chevron'),'link-row'));}
function managementAdvice(kind){const branding=[['Origem e propósito','Conte quem produz, de onde vem e por que esse trabalho merece continuar. Use a história do catálogo como ponto de partida.'],['Promessa de marca','Escolha uma promessa verificável e cumpra no produto, na embalagem e no atendimento.'],['Posicionamento','Deixe claro para quem o produto é e qual benefício justifica seu preço.'],['Identidade consistente','Repita nome, logo, cores e tom de voz no pacote, na banca, no catálogo e nas mensagens.'],['Prova e relacionamento','Mostre origem, preparo e depoimentos autorizados. Anote o que clientes valorizam e teste uma mudança de cada vez.']],pdv=[['Preço fácil de comparar','Mostre nome, apresentação e preço juntos. Mantenha etiquetas legíveis e revise o estoque antes de abrir.'],['Banca que facilita a escolha','Agrupe produtos por uso. Deixe espaço para circular, apontar o celular e pagar sem bloquear a escolha de outra pessoa.'],['Demonstração com propósito','Explique em uma frase o sabor ou o uso. Se oferecer degustação, registre abordagens e vendas para avaliar o resultado.'],['Combinações para testar','Ofereça uma combinação com preço e margem claros. Convide outro produtor depois de definir preço, responsabilidade e estoque.'],['Pagamento e continuidade','Deixe formas de pagamento visíveis. Ao terminar, ofereça o catálogo e peça autorização para avisar sobre a próxima feira.']];return (kind==='branding'?branding:pdv).map(([title,text])=>'<div class="advice-item"><h3>'+title+'</h3><p>'+text+'</p></div>').join('')+'<a class="management-source" href="'+(kind==='branding'?'https://sebrae.com.br/Sebrae/Portal%20Sebrae/UFs/PE/Anexos/Manual%20completo%20de%20branding%20para%20neg%C3%B3cios.pdf':'https://pa.loja.sebrae.com.br/estrategiaparapontodevenda')+'" target="_blank" rel="noopener">Sebrae · '+(kind==='branding'?'branding para negócios':'ponto de venda')+'</a>';}
function managementPage(){const sel=selection(),m=filteredMetrics(sel),events=model.data.events.slice().sort((a,b)=>b.start.localeCompare(a.start));const origin=managementSection('origins','Origem das vendas',reportScopeName(sel.scope),[['all','Dados Totais'],['individual-pf','Pessoa Física'],['individual-pj','CNPJ'],['events','Eventos'],...events.map(e=>[e.id,managementEventName(e)])].map(([id,name])=>btn('management-scope','<span>'+escape(name)+'</span>'+icon(managementScope===id?'check':'chevron'),'scope-option'+(managementScope===id?' selected':''),{scope:id})).join(''));return top()+(isFeira()?feiraHero(sel,m):'')+advisorPanel()+'<div class="management-layout"><div class="management-scopes">'+origin+'</div>'+managementMetrics(sel,m)+managementMonths(sel,events)+managementSection('detail-reports','Resultados e relatórios',grammarCount(m.sales.length,'venda','vendas')+' · Resultado '+E.money(m.result),managementResults(m)+managementRevenue(m)+managementRank(m)+managementPayments(m)+managementSection('clients','Consumo dos clientes','Pessoa física e CNPJ · compras e comparativos','<p class="small muted">Cadastros, consumos e comparação com o mês anterior.</p><div class="two">'+btn('consumption','Pessoa física','choice',{type:'PF'})+btn('consumption','CNPJ','choice',{type:'PJ'})+'</div>')+managementSection('qr','QR codes lidos',qrReadSummary(m.sales),'<p class="small muted">Contadas sozinhas quando o cliente abre seu portfólio pelo QR mostrado após a venda. Sem internet ou com o QR de um evento, toque em QR code lido para registrar.</p>')+managementReports(events,sel,m))+'<section class="panel management-intelligence"><h2>Inteligência agora</h2>'+btn('brain','<span>'+icon('brain')+'<span>Analisar este período<small>Vendas, destinatários, clientes e comparativos</small></span></span>'+icon('chevron'),'link-row brain-entry',{source:'management'})+btn('brain-configuration','Configurar serviço de IA','link')+'</section>'+managementSection('branding',icon('spark')+' Branding','Identidade, origem e relacionamento',managementAdvice('branding'))+managementSection('pdv',icon('store')+' PDV','Preços, exposição e experiência na banca',managementAdvice('pdv'))+'</div>';}
function managementReport(kind){const sel=selection(),m=filteredMetrics(sel);let title='',body='';if(kind==='products'){title='Produtos · '+monthBR(month,true);body=m.rank.length?m.rank.map(r=>'<div class="management-value-row"><span><strong>'+escape(titleName(r.name))+'</strong><small>'+escape(r.description)+' · '+E.quantity(r.qty)+' '+E.unitLabel(r.unit,r.qty)+'</small></span><strong>'+E.money(r.amount)+'</strong></div>').join(''):'<p class="muted">Sem vendas neste período.</p>';body+=btn('export-sales','Baixar vendas do período em CSV','primary modal-action');}else if(kind==='clients'){return consumptionModal(sel.scope==='individual-pj'?'PJ':'PF');}else if(kind==='events'){title='Eventos';body=model.data.events.filter(e=>['all','events'].includes(sel.scope)||e.id===sel.scope).sort((a,b)=>b.start.localeCompare(a.start)).map(e=>{const em=aggregateSales(model.data.sales.filter(s=>s.status==='completed'&&s.scope===e.id),model.data.expenses.filter(x=>x.scope===e.id));return btn('event-detail','<span><strong>'+escape(managementEventName(e))+'</strong><small>'+dateBR(e.start)+' · '+grammarCount(em.sales.length,'venda','vendas')+' · '+E.money(em.revenue)+'</small></span>'+icon('chevron'),'list-row',{id:e.id});}).join('')||(sel.scope==='loja'?'<p class="muted">Vendas individuais ficam fora dos eventos.</p>':'<p class="muted">Nenhum evento nesta origem.</p>');}else if(kind==='stock'){title='Valor do estoque';const snapshot=managementStockSnapshot(sel.scope),products=snapshot.products,valued=products.every(p=>Number.isFinite(p.cost)&&Number.isFinite(p.price)),cost=products.reduce((n,p)=>n+p.stock*(p.cost||0),0),retail=products.reduce((n,p)=>n+p.stock*(p.price||0),0);body=snapshot.known?'<div class="management-value-row"><span>Ao custo atual'+(snapshot.estimated?' · estimado':'')+'</span><strong>'+(valued?E.money(cost):'—')+'</strong></div><div class="management-value-row"><span>Potencial de venda</span><strong>'+(valued?E.money(retail):'—')+'</strong></div><p class="small muted">'+escape(snapshot.note)+(valued?'':' Alguns produtos não têm preço e custo atuais disponíveis; os totais não são calculados.')+' Valores aos preços e custos atuais. O potencial de venda não é receita recebida.</p>'+products.map(p=>'<div class="management-value-row"><span><strong>'+escape(titleName(p.name))+'</strong><small>'+escape(p.description||E.description(p))+' · '+E.quantity(p.stock)+' '+E.unitLabel(p.unit,p.stock)+'</small></span><strong>'+(Number.isFinite(p.cost)?E.money(p.stock*p.cost):'—')+'</strong></div>').join(''):'<p class="muted">'+escape(snapshot.note)+'</p>';}else return;openModal(title,'<p class="small muted">'+escape(reportScopeName(sel.scope))+' · '+escape(kind==='stock'?'Estoque atual':periodText(sel))+'</p>'+body+btn('close-modal','Voltar','choice modal-action'),'management-report');}

function managementEventName(e){return e.id==='demo-inventario'?'Feira do Inventário Rural':e.id==='demo-sexta'?'Feira 3ª Idade às sextas feiras':e.name;}
function top(){if(page==='Estoque')return stockTop();const tools=page==='Gestão'?btn('brain',icon('brain'),'round brain-button',{source:'management'}):page==='Vender'?btn('sales-history',icon('receipt'),'round'):page==='Clientes'||page==='Eventos'?btn(page==='Clientes'?'new-client':'new-event',icon('plus'),page==='Eventos'?'round event-plus':'round blue'):'';const identity=['Vender','Clientes','Gestão'].includes(page)?btn('profile','<img src="'+escape(model.data.settings.photo||PROFILE_PHOTO)+'" alt="'+(model.data.settings.photo?escape(model.data.settings.producerName):'Retrato fictício de Luiz Claudio')+'"><span>'+escape(model.data.settings.producerName)+'</span>'+icon('down'),'profile-pill'):btn('scope',icon('store')+' '+escape(scopeName(scope))+' '+icon('down'),'scope');return '<div class="topbar">'+identity+'<div class="top-actions">'+tools+btn('settings',icon('settings'),'round')+'</div></div><div class="page-title"><h1>'+(page==='Vender'?'Produtos':pageLabel(page))+'</h1>'+(page==='Clientes'?btn('clients-search',icon('search'),'title-search'):'')+'</div>'+(page==='Vender'?salesContext():'');}
function upcomingEvents(){return model.data.events.filter(e=>e.status==='active'&&eventEndTime(e)>Date.now()).sort((a,b)=>eventStartTime(a)-eventStartTime(b));}
function consentFooter(){return '\n\nPara concordar em receber nossos avisos de feiras pelo WhatsApp, responda CONCORDO. Para deixar de receber, responda SAIR.';}
function eventNoticeLine(e){return '🌿 '+e.name+'\n📅 '+eventDateLabel(e)+'\n📍 '+e.place;}
function clientInvitation(c,e){return 'Olá, '+c.name+'!\n\n'+model.data.catalog.title+' convida você:\n'+eventNoticeLine(e)+'\n\nSerá um prazer encontrar você na feira!'+(safePublicURL(model.data.catalog.publicUrl)?'\nCatálogo: '+safePublicURL(model.data.catalog.publicUrl):'')+'\n'+model.data.settings.producerName+consentFooter();}
function broadcastText(events){const url=safePublicURL(model.data.settings.eventsURL||'');return 'Olá! 🌿\n\nConfira os próximos encontros com '+model.data.catalog.title+':\n\n'+events.map(eventNoticeLine).join('\n\n')+(url?'\n\nProgramação: '+url:'')+'\n\nEsperamos você!\n'+model.data.settings.producerName+consentFooter();}
function broadcastModal(id){const events=upcomingEvents(),selected=id?events.filter(e=>e.id===id):events;openModal('Aviso para vários clientes',events.length?'<label for="broadcast-event">Próximos eventos</label><select id="broadcast-event"><option value="">Todos os próximos eventos</option>'+events.map(e=>'<option value="'+escape(e.id)+'"'+(e.id===id?' selected':'')+'>'+escape(e.name)+'</option>').join('')+'</select>'+field('events-public-link','Link público da programação (opcional)',model.data.settings.eventsURL||'','type="url" placeholder="https://..."')+btn('broadcast-link-save','Salvar link e atualizar aviso','choice')+'<label for="broadcast-message">Aviso para a lista de transmissão</label><textarea id="broadcast-message" class="notice-copy-text">'+escape(broadcastText(selected))+'</textarea>'+btn('broadcast-copy','Copiar aviso','success modal-action')+'<p class="pdf-share-note">Cole na sua lista de transmissão do WhatsApp. A mensagem pede a concordância do cliente; registre a autorização no cadastro depois que ele responder. Para quem pediu SAIR, interrompa os avisos.</p>':'<p class="dialog-text">Crie um evento futuro para preparar a mensagem.</p>'+btn('broadcast-events','Ver eventos','primary'),'broadcast',{event:id||''});}
async function copyBroadcast(){const el=document.getElementById('broadcast-message');if(!el)return;try{if(navigator.clipboard&&navigator.clipboard.writeText){await navigator.clipboard.writeText(el.value);return toast('Aviso copiado. Cole na lista de transmissão.');}}catch(e){}el.focus();el.select();toast(document.execCommand&&document.execCommand('copy')?'Aviso copiado. Cole na lista de transmissão.':'Aviso selecionado. Use Copiar e cole na lista.');}
function clientsPage(){const ranking=clientRanking(),rank=new Map(ranking.slice(0,3).map((c,index)=>[c.id,index])),n=E.normalize(clientQuery),list=model.data.clients.filter(c=>!n||E.normalize([c.name,c.city,c.neighborhood,c.phone,c.document].filter(Boolean).join(' ')).includes(n)).sort((a,b)=>(ranking.findIndex(c=>c.id===a.id)<0?999:ranking.findIndex(c=>c.id===a.id))-(ranking.findIndex(c=>c.id===b.id)<0?999:ranking.findIndex(c=>c.id===b.id))||a.name.localeCompare(b.name,'pt-BR')),e=model.data.events.find(e=>e.id===notifyEventId&&e.status==='active'),next=upcomingEvents();return top()+'<div class="clients-layout"><section class="panel upcoming-notice"><h2>Próximos eventos</h2><p>'+escape(next.length?next[0].name+' · '+eventDateLabel(next[0]):'Nenhum evento futuro cadastrado.')+'</p><div class="two">'+btn('broadcast','Copiar aviso para vários clientes','success')+btn('broadcast-events','Ver programação','choice')+'</div>'+(safePublicURL(model.data.settings.eventsURL||'')?'<a class="public-events-link" href="'+escape(safePublicURL(model.data.settings.eventsURL))+'" target="_blank" rel="noopener">Abrir link da programação '+icon('arrow')+'</a>':'')+'</section>'+btn('catalog','<span><strong>Catálogo</strong><small>Mostre seus produtos aos clientes</small></span>'+icon('image')+icon('chevron'),'catalog-entry')+(e?'<section class="client-event-notice"><strong>Avise os Clientes · '+escape(e.name)+'</strong><p>'+escape(eventDateLabel(e))+' · '+escape(e.place)+'</p>'+btn('notice-clear-event','Trocar evento','link')+'</section>':'')+(clientSearchOpen?'<div class="search clients-search">'+icon('search')+'<label class="sr-only" for="client-search">Buscar clientes</label><input id="client-search" placeholder="Nome, cidade, bairro ou documento" value="'+escape(clientQuery)+'" autocomplete="off"></div>':'')+btn('clients-toggle','<span>Clientes cadastrados<small>'+grammarCount(list.length,'cliente','clientes')+'</small></span>'+icon(clientsOpen?'down':'chevron'),'clients-summary-toggle')+(clientsOpen?'<div class="client-list">'+(list.length?list.map(c=>{const sales=model.data.sales.filter(s=>s.status==='completed'&&s.customerId===c.id),total=sales.reduce((v,s)=>v+s.total,0),position=rank.get(c.id);return '<article class="client-card">'+btn('client-detail','<strong>'+(position!==undefined?'<span class="client-medal '+['gold','silver','bronze'][position]+'" role="img" aria-label="'+(position+1)+'º em compras">'+starIcon()+'</span>':'')+escape(c.name)+'</strong><small>'+escape([c.city,c.neighborhood].filter(Boolean).join(' · ')||'Origem não informada')+'</small><small>'+(c.personType==='PJ'?'CNPJ · ':'')+grammarCount(sales.length,'compra','compras')+' · '+E.money(total)+'</small>','client-main',{id:c.id})+btn('client-notice','Avisar','client-notice-pill',{id:c.id})+'</article>';}).join(''):'<p class="empty">Nenhum cliente encontrado.</p>')+'</div>':'')+'<section class="panel anonymous-clients"><h2>Clientes não identificados</h2><p class="muted">'+grammarCount(model.data.sales.filter(s=>s.status==='completed'&&!s.customerId).length,'venda sem nome de cliente','vendas sem nome de cliente')+'</p></section>'+btn('export-clients',icon('download')+' Exportar clientes','link-row export-client-row')+'</div>';}
function customerModal(client){clientEditor={name:'',phone:'',uf:'MG',city:'',neighborhood:'',aiConsent:false,personType:'PF',document:'',noticeConsent:false,...client,neighborhoodExpanded:false,customNeighborhood:false};paintCustomer();}
function paintCustomer(){const c=clientEditor;openModal(c.id?'Editar cliente':'Novo Cliente','<label for="client-type">Tipo de cliente</label><select id="client-type"><option value="PF"'+(c.personType!=='PJ'?' selected':'')+'>Pessoa física</option><option value="PJ"'+(c.personType==='PJ'?' selected':'')+'>Pessoa jurídica · CNPJ</option></select>'+field('client-name',c.personType==='PJ'?'Empresa / nome fantasia':'Nome',c.name,'autocomplete="name"')+field('client-document',c.personType==='PJ'?'CNPJ (opcional)':'CPF (opcional)',c.document||'','autocomplete="off"')+field('client-phone','WhatsApp (opcional)',c.phone||'','type="tel" inputmode="tel" placeholder="(32) 99999-9999"')+'<label>Localidade</label>'+neighborhoodControls(c,'client')+field('client-city','Município',c.city,'placeholder="Carangola"')+(!isCarangola(c)&&!c.customNeighborhood?field('client-neighborhood','Bairro',c.neighborhood||''):'')+'<label for="client-uf">Estado</label><select id="client-uf">'+E.STATES.map(s=>'<option value="'+s[0]+'"'+(s[0]===c.uf?' selected':'')+'>'+s[0]+' · '+s[1]+'</option>').join('')+'</select><label class="consent-row"><input type="checkbox" id="client-notice-consent"'+(c.noticeConsent?' checked':'')+'> Cliente respondeu CONCORDO e autorizou avisos de feiras</label><label class="consent-row"><input type="checkbox" id="client-ai-consent"'+(c.aiConsent?' checked':'')+'> Cliente autoriza incluir seu nome na análise com IA</label>'+btn('save-client','Salvar Cliente','success modal-action'),'client',{id:c.id});}
function captureClient(){if(!clientEditor)return;for(const [id,key] of [['client-name','name'],['client-phone','phone'],['client-city','city'],['client-neighborhood','neighborhood'],['client-uf','uf'],['client-type','personType'],['client-document','document']]){const el=document.getElementById(id);if(el)clientEditor[key]=el.value;}for(const [id,key] of [['client-ai-consent','aiConsent'],['client-notice-consent','noticeConsent']]){const el=document.getElementById(id);if(el)clientEditor[key]=el.checked;}}
function clientConsumption(id,sel){const c=model.data.clients.find(c=>c.id===id),m=filteredMetrics({...sel,customerId:id}),prior=filteredMetrics({...previousSelection(sel),customerId:id});return {client:c,metrics:m,previous:prior};}
function consumptionModal(type){consumptionType=type==='PJ'?'PJ':'PF';const n=E.normalize(consumptionQuery),list=model.data.clients.filter(c=>c.personType===consumptionType&&(!n||E.normalize(c.name+' '+(c.document||'')+' '+c.city).includes(n))),sel=selection();openModal(consumptionType==='PJ'?'Consumo · CNPJ':'Consumo · pessoa física','<p class="small muted">'+escape(periodText(sel))+' · '+escape(reportScopeName(sel.scope))+'</p>'+field('consumption-search','Pesquisar cliente',consumptionQuery,'type="search" placeholder="Nome, município ou documento"')+'<div class="modal-list">'+(list.length?list.map(c=>{const r=clientConsumption(c.id,sel);return btn('consumption-detail','<span><strong>'+escape(c.name)+'</strong><small>'+grammarCount(r.metrics.sales.length,'compra','compras')+' · '+E.money(r.metrics.revenue)+'<br>Mês anterior: '+E.money(r.previous.revenue)+'</small></span>'+icon('chevron'),'list-row',{id:c.id});}).join(''):'<p class="dialog-text">Nenhum cadastro deste tipo.</p>'+btn('new-business','Cadastrar CNPJ','choice')+'')+'</div>'+btn('export-consumption',icon('download')+' CSV mensal','primary modal-action',{type:consumptionType})+btn('close-modal','Voltar','choice modal-action'),'consumption',{type:consumptionType});}
function consumptionDetail(id){const r=clientConsumption(id,selection()),c=r.client;if(!c)return;openModal(c.name,'<p class="dialog-text">'+escape([c.personType==='PJ'?'CNPJ':'Pessoa física',c.document,c.city,c.neighborhood].filter(Boolean).join(' · '))+'</p><section class="panel"><div class="row"><span>Consumo no recorte</span><strong>'+E.money(r.metrics.revenue)+'</strong></div><p>'+grammarCount(r.metrics.sales.length,'compra','compras')+' · ticket '+E.money(r.metrics.ticket)+'</p><p>Mês anterior equivalente: '+E.money(r.previous.revenue)+' ('+grammarCount(r.previous.sales.length,'compra','compras')+').</p></section><div class="modal-list">'+r.metrics.rank.map(i=>'<div class="list-row"><span><strong>'+escape(titleName(i.name))+'</strong><small>'+escape(i.description)+' · '+E.quantity(i.qty)+' '+escape(E.unitLabel(i.unit,i.qty))+'</small></span><strong>'+E.money(i.amount)+'</strong></div>').join('')+'</div><div class="two">'+btn('customer-records','Ver vendas','choice',{id})+btn('brain','Comparativos '+icon('brain'),'choice',{source:'customer',id})+'</div>'+btn('edit-client','Checar cadastro','primary modal-action',{id})+btn('consumption','Voltar à lista','choice modal-action',{type:c.personType}),'consumption-detail',{id});}
function consumptionRows(type){const sel={month,scope:'all',days:[]},rows=[['Registro','Mês','Tipo','Cliente','Documento','Município','Bairro','Compras','Receita líquida','Mês anterior','Variação R$','Venda','Data','Local','Produto','Apresentação','Quantidade','Unidade','Receita atribuída']];model.data.clients.filter(c=>c.personType===type).forEach(c=>{const r=clientConsumption(c.id,sel);rows.push(['Resumo',month,type,c.name,c.document||'',c.city,c.neighborhood,r.metrics.sales.length,(r.metrics.revenue/100).toFixed(2),(r.previous.revenue/100).toFixed(2),((r.metrics.revenue-r.previous.revenue)/100).toFixed(2)]);r.metrics.sales.forEach(s=>netItems(s).forEach(i=>rows.push(['Item',month,type,c.name,'',c.city,c.neighborhood,'','','','',s.id,s.date,reportScopeName(s.scope),i.name,i.description,i.qty,i.unit,(i.amount/100).toFixed(2)])));});return rows;}
function fairGeneralRows(id){const previous=dataScope;try{dataScope=id;const rows=generalRows(),headers=rows[0];const e=model.data.events.find(e=>e.id===id);if(e){const row=Array(headers.length).fill('');row[headers.indexOf('Registro')]='Encerramento do evento';row[headers.indexOf('ID')]=e.id;row[headers.indexOf('Data')]=e.finishedAt||'';row[headers.indexOf('Local')]=e.name;row[headers.indexOf('Status')]=e.status;row[headers.indexOf('Descrição')]=e.closedAutomatically?'Encerramento automático':'Horário de Brasília';row[headers.indexOf('Início')]=e.start+' '+e.from;row[headers.indexOf('Fim')]=e.end+' '+e.until;rows.push(row);}const load=eventLoad(id);if(load){load.items.forEach(i=>{const row=Array(headers.length).fill('');row[headers.indexOf('Registro')]='Produtos levados';row[headers.indexOf('ID')]=i.productId;row[headers.indexOf('Data')]=load.updatedAt;row[headers.indexOf('Local')]=e?.name||id;row[headers.indexOf('Produto')]=i.name;row[headers.indexOf('Apresentação')]=i.description;row[headers.indexOf('Unidade')]=i.unit;row[headers.indexOf('Quantidade')]=i.qty;row[headers.indexOf('Descrição')]='Total levado informado, incluindo reposições';rows.push(row);});}return rows;}finally{dataScope=previous;}}
function eventModal(){const today=E.dayKey(new Date());openModal('Novo Evento',field('event-name','Nome do evento','','placeholder="Feira do Inventário Rural"')+field('event-place','Local','','placeholder="Praça de Carangola"')+'<div class="two">'+field('event-city','Município',model.data.settings.city||'Carangola')+field('event-uf','UF',model.data.settings.uf||'MG','maxlength="2"')+'</div><div class="two event-date-fields">'+field('event-start','Primeiro dia',today,'type="date"')+field('event-end','Último dia',today,'type="date"')+'</div><div class="two">'+field('event-from','Início','08:00','type="time"')+field('event-until','Fim','18:00','type="time"')+'</div><p class="event-qr">O evento é encerrado ao atingir a data e o horário finais, no horário de Brasília. Se o app estiver fechado, atualiza ao abrir novamente.</p>'+btn('save-event','Criar evento','success modal-action'),'event');}
function brainSelection(source,id){if(source==='customer')return {...selection(),customerId:id};if(source==='event'){const e=model.data.events.find(e=>e.id===id);return {month:e.start.slice(0,7),scope:e.id,days:[],eventId:e.id};}if(source==='management')return selection();const e=model.data.events.find(e=>e.id===scope);return e?{month:e.start.slice(0,7),scope:e.id,days:[],eventId:e.id}:{month:E.monthKey(new Date()),scope:'loja',days:[E.dayKey(new Date())]};}
function eventSalesInWindow(e,reference,sel,now){let dayOffsets=null;if(sel.days&&sel.days.length)dayOffsets=sel.days.map(day=>Math.round((Date.parse(day+'T12:00:00Z')-Date.parse(reference.start+'T12:00:00Z'))/86400000));const during=now>=eventStartTime(reference)&&now<eventEndTime(reference),time=brTime(now),today=E.dayKey(now),elapsed=Math.round((Date.parse(today+'T12:00:00Z')-Date.parse(reference.start+'T12:00:00Z'))/86400000),from=sel.from||(during?time.slice(0,2)+':00':reference.from),until=sel.until||(during?time:reference.until),offsets=dayOffsets||(during?[elapsed]:null);return model.data.sales.filter(s=>{if(s.status!=='completed'||s.scope!==e.id||(sel.customerId&&s.customerId!==sel.customerId))return false;const stamp=Date.parse(s.date),day=E.dayKey(s.date),offset=Math.round((Date.parse(day+'T12:00:00Z')-Date.parse(e.start+'T12:00:00Z'))/86400000),clock=brTime(s.date);return stamp>=eventStartTime(e)&&stamp<eventEndTime(e)&&stamp<=now&&(!offsets||offsets.includes(offset))&&clock>=from&&clock<until;});}
