function brainOpen(source,id){ensureManagementData();const sel=brainSelection(source||'management',id),events=model.data.events.slice().sort((a,b)=>b.start.localeCompare(a.start)),current=events.find(e=>e.id===sel.scope),previous=current&&events.filter(e=>e.id!==current.id&&e.start<current.start).sort((a,b)=>b.start.localeCompare(a.start))[0];brainContext={source:source||'management',sel,baseSel:{...sel},currentId:current?current.id:'',previousId:previous?previous.id:'',stamp:Date.now()};paintBrain();loadBrainWeather();}
function brainWeatherEvent(){return brainContext&&model.data.events.find(e=>e.id===brainContext.sel.scope)||upcomingEvents()[0];}
function weatherKey(e){return [e.id,e.start,e.end,e.from,e.until,e.city||model.data.settings.city,e.uf||model.data.settings.uf].join('|');}
async function weatherJSON(url){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000);try{const response=await fetch(url,{signal:controller.signal});if(!response.ok)throw Error('Previsão indisponível.');return await response.json();}finally{clearTimeout(timer);}}
