 const p=candidates[0],f=await weatherJSON('https://api.open-meteo.com/v1/forecast?latitude='+p.latitude+'&longitude='+p.longitude+'&hourly=precipitation_probability,precipitation&forecast_days=16&timezone=America%2FSao_Paulo'),h=f.hourly||{},windows=[];
 for(let t=Date.parse(firstDay+'T12:00:00Z'),count=0;t<=Date.parse(e.end+'T12:00:00Z')&&count<10;t+=86400000,count++){const d=new Date(t).toISOString().slice(0,10),start=Math.max(now,Date.parse(d+'T'+e.from+':00-03:00')),end=Date.parse(d+'T'+e.until+':00-03:00');if(end>start)windows.push([start,end]);}
