 'coffee-type':d=>{const v=productForm.variants[+d.index],pr=E.COFFEE_PROFILES[d.value];Object.assign(v,{type:d.value,format:pr.format,unit:pr.unit,weight:pr.weight,volume:0});autoValues(+d.index);render();},
