 digit:d=>{const item=draft.items[draft.active];let value=item.rawQty;if(d.digit===','){if(!/[,.]/.test(value))value+=',';}else value=value==='0'?d.digit:(value+d.digit).slice(0,9);if(setSaleQuantity(value))render();},
