 'choose-client':()=>openModal('Cliente cadastrado','<div class="modal-list">'+model.data.clients.map(c=>btn('pick-client','<span>'+escape(c.name)+'</span><span class="muted">'+escape(c.uf)+'</span>','link-row',{id:c.id})).join('')+'</div>','pick-client'),
