 'open-cart':()=>openCart(),
 'finalize-purchase':()=>finalizePurchase(),
 'continue-shopping':()=>continueShopping(),
 'edit-cart-item':d=>{if(!draft)return;const index=+d.index;if(!draft.items[index])return;closeModal();selectDiscountItem(index);page='Venda';render();window.scrollTo(0,0);},
 'remove-cart-item':d=>{if(!draft||!pendingCheckout||pendingCheckout.stage!=='cart')return;const index=+d.index;if(!draft.items[index])return;saveActiveDiscount();draft.items.splice(index,1);if(index<draft.active)draft.active--;draft.active=Math.min(draft.active,draft.items.length-1);if(!draft.items.length){pendingCheckout=null;draft=null;closeModal();page='Vender';render();toast('Carrinho vazio. Escolha um produto.');return;}loadActiveDiscount();splitUpdate();render();paintCheckout();},
