 'locality-pick':d=>{const c=localityTarget(d.context);if(!c||!CARANGOLA_NEIGHBORHOODS.includes(d.value))return;c.city='Carangola';c.uf='MG';c.neighborhood=d.value;c.statesExpanded=false;c.neighborhoodExpanded=false;c.customNeighborhood=false;paintLocality(d.context);},
 'locality-custom':d=>{const c=localityTarget(d.context);if(!c)return;c.neighborhoodExpanded=false;c.customNeighborhood=true;paintLocality(d.context);const el=document.getElementById(d.context==='client'?'client-neighborhood':d.context==='checkout'?'checkout-neighborhood':'sale-client-neighborhood');if(el)el.focus();},
 'locality-other':d=>{const c=localityTarget(d.context);if(!c)return;c.city='';c.neighborhood='';c.neighborhoodExpanded=false;c.customNeighborhood=false;if(d.context==='sale'||d.context==='checkout'){draft.clientExpanded=true;if(d.context==='checkout'){closeModal();page='Venda';}}paintLocality(d.context==='checkout'?'sale':d.context);},
 'close-modal':()=>closeModal(),
 settings:()=>settings(),
 scope:()=>openModal('Vendendo em','<div class="modal-list">'+btn('set-scope',icon('store')+' Loja','link-row',{id:'loja'})+model.data.events.filter(e=>e.status==='active').map(e=>btn('set-scope',escape(e.name),'link-row',{id:e.id})).join('')+'</div>'+btn('scope-new-event','Criar evento','link'),'scope'),
