 'period-sales':()=>salesHistory(model.metrics(month,managementScope).sales,'Vendas do período'),
 'month-shift':d=>{const date=new Date(month+'-15T12:00:00Z');date.setUTCMonth(date.getUTCMonth()+Number(d.delta));month=date.toISOString().slice(0,7);render();},
 'choose-month':()=>openModal('Escolher período',field('month-input','Mês',month,'type="month"')+btn('apply-month','Aplicar','primary modal-action'),'month'),
