 'day-sales':d=>salesHistory(model.metrics(month,managementScope).sales.filter(s=>Number(E.dayKey(s.date).slice(-2))===+d.day),'Vendas do dia '+d.day),
 'rank-detail':d=>{const m=model.metrics(month,managementScope),r=m.rank.find(r=>r.id===d.id);if(r)info(r.name,E.quantity(r.qty)+' unidades de venda no período. Receita líquida atribuída: '+E.money(r.amount)+'. '+r.description);},
 'payment-detail':d=>salesHistory(model.metrics(month,managementScope).sales.filter(s=>s.payments.some(p=>p.method===d.method)),'Vendas · '+d.method),
 'peak-detail':()=>info('Horário de pico','Faixa de uma hora com mais vendas concluídas no período, considerando o horário de Brasília.'),
 'local-insights':()=>{const m=model.metrics(month,managementScope),low=model.data.products.filter(p=>p.stock<=p.min),parts=[];parts.push(m.sales.length?'Você registrou '+grammarCount(m.sales.length,'venda','vendas')+', com ticket médio de '+E.money(m.ticket)+'.':'O período ainda não tem vendas concluídas.');if(m.rank[0])parts.push(m.rank[0].name+' lidera a receita do período com '+E.money(m.rank[0].amount)+'.');parts.push(low.length?low.length+' opções precisam de atenção no estoque: '+low.map(p=>p.name).join(', ')+'.':'Os produtos estão acima do estoque mínimo.');openModal('Analisar este período',parts.map(p=>'<p class="insight-item">'+escape(p)+'</p>').join('')+btn('close-modal','Entendi','success modal-action'),'insights');},
 'new-client':()=>customerModal(),
 'client-detail':d=>{const c=model.data.clients.find(c=>c.id===d.id),sales=model.data.sales.filter(s=>s.status==='completed'&&s.customerId===c.id);openModal(c.name,'<p class="dialog-text">'+escape([c.city,c.neighborhood,c.uf].filter(Boolean).join(' · ')||'Origem não informada')+'</p><div class="panel"><p>'+grammarCount(sales.length,'compra','compras')+'</p><p class="receipt-number">'+E.money(sales.reduce((s,v)=>s+v.total,0))+'</p><p class="small muted">Total em compras concluídas</p></div>'+btn('edit-client','Editar cliente','primary',{id:c.id}),'client-detail');},
 'edit-client':d=>customerModal(model.data.clients.find(c=>c.id===d.id)),
 'save-client':()=>{captureClient();const name=clientEditor.name.trim();if(!name)return toast('Informe o nome do cliente.');if(clientEditor.phone&&!whatsappNumber(clientEditor.phone))return toast('Informe um telefone com DDD válido.');const c={id:clientEditor.id||E.uid(),name,phone:clientEditor.phone||'',city:clientEditor.city.trim(),neighborhood:clientEditor.neighborhood.trim(),uf:clientEditor.uf,aiConsent:clientEditor.aiConsent};if(isCarangola(c))c.uf='MG';const i=model.data.clients.findIndex(x=>x.id===c.id);if(i>=0)model.data.clients[i]=c;else model.data.clients.push(c);persist();closeModal();render();toast('Cliente salvo.');},
 'new-event':()=>eventModal(),
 'save-event':()=>{const name=document.getElementById('event-name').value.trim(),place=document.getElementById('event-place').value.trim(),start=document.getElementById('event-start').value,end=document.getElementById('event-end').value,from=document.getElementById('event-from').value,until=document.getElementById('event-until').value,days=(new Date(end)-new Date(start))/86400000+1;if(!name||!place||!start||!end||days<1||days>9||!from||!until)return toast('Informe nome, local e datas de 1 a 9 dias.');model.data.events.push({id:E.uid(),name,place,start,end,from,until,status:'active',qrKind:E.normalize(name).includes('inventario')?'site':'catalog',website:E.normalize(name).includes('inventario')?'https://www.visitecarangolamg.com.br':''});persist();closeModal();render();toast('Evento criado.');},
 'event-detail':d=>{const e=model.data.events.find(e=>e.id===d.id),sales=model.data.sales.filter(s=>s.scope===e.id&&s.status==='completed');openModal(e.name,'<p class="dialog-text">'+escape(e.place)+' · '+dateBR(e.start)+' a '+dateBR(e.end)+'<br>'+e.from+' às '+e.until+'</p><p>'+grammarCount(sales.length,'venda','vendas')+' · '+E.money(sales.reduce((v,s)=>v+s.total,0))+'</p>'+btn('event-use',e.status==='active'?'Vender neste evento':'Ver na Gestão','primary modal-action',{id:e.id})+(e.status==='active'?btn('finish-event','Finalizar Evento','soft-danger modal-action',{id:e.id}):''),'event-detail');},
 'event-use':d=>{const e=model.data.events.find(e=>e.id===d.id);scope=e.id;if(e.status==='active')page='Vender';else{page='Gestão';managementScope=e.id;month=e.start.slice(0,7);}closeModal();render();},
 'finish-event':d=>{model.data.events.find(e=>e.id===d.id).status='finished';if(scope===d.id)scope='loja';persist();closeModal();render();toast('Evento finalizado. As vendas continuam na Gestão.');},
 expense:()=>openModal('Adicionar despesa',field('expense-title','Descrição','','placeholder="Ex.: transporte"')+field('expense-value','Valor (R$)','','inputmode="decimal"')+field('expense-date','Data',month+'-10','type="date"')+btn('save-expense','Registrar despesa','primary modal-action'),'expense'),
 'save-expense':()=>{const title=document.getElementById('expense-title').value.trim(),amount=E.cents(document.getElementById('expense-value').value),date=document.getElementById('expense-date').value;if(!title||!Number.isFinite(amount)||amount<=0||!date)return toast('Informe descrição, valor e data.');model.data.expenses.unshift({id:E.uid(),title,amount,date:date+'T12:00:00-03:00',scope:managementScope==='all'?scope:managementScope});persist();closeModal();render();toast('Despesa registrada.');},
 'export-sales':()=>exportCSV('vendas-'+month+'.csv',saleCSVRows(model.metrics(month,managementScope).sales)),
 'export-stock':()=>exportCSV('estoque.csv',[['Produto','Categoria','Apresentação','Unidade','Estoque','Mínimo','Preço','Custo'],...model.data.products.map(p=>[p.name,p.category,E.description(p),p.unit,p.stock,p.min,(p.price/100).toFixed(2),(p.cost/100).toFixed(2)])]),
 'export-clients':()=>exportCSV('clientes.csv',[['Nome','Município','Bairro','UF','Compras','Total'],...model.data.clients.map(c=>{const s=model.data.sales.filter(s=>s.status==='completed'&&s.customerId===c.id);return[c.name,c.city,c.neighborhood,c.uf,s.length,(s.reduce((n,v)=>n+v.total,0)/100).toFixed(2)];})]),
