 'save-expense':()=>{const title=document.getElementById('expense-title').value.trim(),amount=E.cents(document.getElementById('expense-value').value),date=document.getElementById('expense-date').value,category=document.getElementById('expense-category').value;if(!title||!Number.isFinite(amount)||amount<=0||!date)return toast('Informe descrição, valor e data.');model.data.expenses.unshift({id:E.uid(),title,amount,date:date+'T12:00:00-03:00',scope:managementScope==='all'?scope:managementScope,category});persist();closeModal();render();toast('Despesa registrada.');}
