function activeEventsAt(now){const stamp=now==null?Date.now():Number(now);return model.data.events.filter(e=>E.eventSellingNow(e,stamp)).sort((a,b)=>a.start.localeCompare(b.start)||a.from.localeCompare(b.from)||a.id.localeCompare(b.id));}

function eventChoice(now){const live=activeEventsAt(now),preferred=live.find(e=>e.id===preferredSaleEvent)||live.find(e=>e.id===scope);if(preferred)return preferred;if(live.length)return live[0];return model.data.events.filter(e=>e.status==='active'&&eventEndTime(e)>(now==null?Date.now():Number(now))).sort((a,b)=>eventStartTime(a)-eventStartTime(b)||a.id.localeCompare(b.id))[0]||null;}

function recipientOptions(now){const event=eventChoice(now),live=!!event&&E.eventSellingNow(event,now==null?Date.now():Number(now));return{pf:!live,pj:!live,event:live,eventRecord:event};}

function syncSellingScope(now){const e=eventChoice(now),next=e&&E.eventSellingNow(e,now==null?Date.now():Number(now))?e.id:'loja',changed=scope!==next;scope=next;stockView='all';stockMenuOpen=false;return changed;}

function presentationText(value){return String(value).split(' · ').map(part=>/^\d+(?:[,.]\d+)?\s*(g|kg|ml|L)$/.test(part)?part:titleName(part)).join(' · ');}
function stockCardDescription(p){const description=E.description(p),unit=E.unitLabel(p.unit,1);return presentationText(E.normalize(description).includes(E.normalize(unit))?description:description+' · '+unit);}
function sellingCardDescription(p){if(p.category==='Cafés'){const format=E.normalize(p.format);return /grao|^verde$/.test(format)?'Grãos':presentationText(p.format||'Moído');}return ['kg','Litro'].includes(p.unit)?'Granel':titleName(E.unitLabel(p.unit||'Unidade',1));}

function eventCard(e,history){const live=E.eventSellingNow(e,Date.now()),ended=e.status==='finished',label=ended?'FINALIZADO':live?'ATIVO':'AGENDADO';return '<section class="panel event-card"><div class="row"><span class="event-title">'+escape(e.name)+'</span><span class="badge event-status '+(live?'event-active':ended?'event-finished':'event-scheduled')+'">'+label+'</span></div><p class="event-meta">'+escape(e.place)+' · '+dateBR(e.start)+(e.end!==e.start?' a '+dateBR(e.end):'')+'<br>'+escape(e.from+' às '+e.until)+' · Brasília</p><div class="two event-main-actions">'+btn('event-detail','Ver evento','link-row event-view',{id:e.id})+btn('event-use',ended?'Ver resultado':'Vender no evento','link-row '+(ended?'event-view':'event-sell'),{id:e.id},!ended&&!live)+'</div>'+(!ended?'<p class="reminder-times">Lembretes: 5, 3 e 1 dia antes da feira.</p><div class="event-reminder-actions">'+btn('event-notify','Avise os Clientes','event-notify',{id:e.id})+btn('event-calendar','Salvar lembretes na agenda','link-row',{id:e.id})+'</div>':'')+'</section>';}

function recipientControls(sale){const state=recipientOptions(),event=sale&&sale.scope!=='loja'?model.data.events.find(e=>e.id===sale.scope):state.eventRecord,done=!!sale,label=event?managementEventName(event):'Evento',detail=event?dateBR(event.start)+(event.end!==event.start?' a '+dateBR(event.end):'')+' · '+event.from+' às '+event.until:'Nenhum evento agendado',selected=sale?.recipientType||sale?.sourceType;return '<section class="recipient-selection" aria-labelledby="recipient-question"><h3 id="recipient-question">Para quem você está vendendo?</h3><div class="recipient-event">'+btn('choose-sale-recipient','<strong>'+escape(label)+'</strong><small>'+escape(detail)+'</small>','recipient-button recipient-gold'+(selected==='EVENT'?' selected':''),{type:'EVENT',id:event?.id||''},done||!state.event)+'</div>'+eventCompanyControl(sale,state)+'<div class="two recipient-people">'+btn('choose-sale-recipient','PESSOA FÍSICA','recipient-button recipient-blue'+(selected==='PF'?' selected':''),{type:'PF'},done||!state.pf)+btn('choose-sale-recipient','EMPRESA','recipient-button recipient-purple'+(selected==='PJ'?' selected':''),{type:'PJ'},done||!state.pj)+'</div>'+(done?'<div class="sale-finished-status" role="status">'+icon('check')+'<span>Venda Finalizada</span></div><p class="recipient-saved">Registrada em '+escape(saleSourceName(sale))+'.</p>':'<p class="recipient-help" role="status">Toque no destino para registrar a venda.</p>')+'</section>';}

function saleSourceName(sale){if(sale.scope!=='loja')return scopeName(sale.scope);return recordPersonType(sale)==='PJ'?'Empresa / CNPJ':'Pessoa Física';}

function saleQuoteFingerprint(q){return JSON.stringify({subtotal:q.subtotal,discount:q.discount,total:q.total,cost:q.cost,items:q.items.map(i=>({productId:i.productId,qty:i.qty,price:i.price,cost:i.cost,discount:i.discount,netTotal:i.netTotal}))});}
function chooseSaleRecipient(type,id){
 if(!recipientPending||recipientPending.busy||!draft||modal?.kind!=='story'||!modal.data?.pending)return;const state=recipientOptions();if(!['PF','PJ','EVENT'].includes(type))return;
 if(type==='EVENT'&&(!state.event||state.eventRecord?.id!==id)||type==='PF'&&!state.pf||type==='PJ'&&!state.pj){storyModal();return toast('O horário do evento mudou. Confira o destino disponível.');}
 if(saleQuoteFingerprint(model.quote(recipientPending.draft))!==saleQuoteFingerprint(recipientPending.summary))return toast('Os valores da compra mudaram. Volte ao carrinho e confira o total.');
 recipientPending.busy=true;const data={...recipientPending.draft,scope:type==='EVENT'?id:'loja',recipientType:type,customerType:type==='EVENT'?(eventCompanyOn()?'PJ':'PF'):type};
 try{
  const next=new E.ERPModel(JSON.parse(JSON.stringify(model.data))),sale=next.complete(data),destination=storyDestination(sale.scope);sale.qrKind=destination.kind;sale.qrPayload=storyPayload(destination,recipientPending);sale.qrRef=portfolioTracked(destination)?recipientPending.qrRef:'';sale.qrReadSource=recipientPending.qrReadSource||'';sale.qrTitle=destination.title;sale.qrReadAt=recipientPending.qrReadAt;sale.customerDocument=next.data.clients.find(c=>c.id===sale.customerId)?.document||'';sale.recordedAfterClose=false;
  const prior=model;model=next;if(!persist()){model=prior;recipientPending.busy=false;return toast('Não foi possível salvar a venda. Libere espaço e tente novamente.');}
  for(const key of ['products','events','clients']){const known=new Map(prior.data[key].map(record=>[record.id,record]));next.data[key]=next.data[key].map(record=>{const current=known.get(record.id);return current?Object.assign(current,record):record;});}prior.data=next.data;model=prior;
  recipientPending=null;pendingCheckout=null;draft=null;closeModal();page='Vender';render();toast('Venda Finalizada. Estoque geral atualizado.');
 }catch(error){recipientPending.busy=false;toast(error.message);}
}

function stockDiagnostic(){
 const allGroups=new Map();for(const p of model.data.products){if(!allGroups.has(p.category))allGroups.set(p.category,[]);allGroups.get(p.category).push(p);}
 const all=[...allGroups.values()].flat(),expanded=!!brainContext?.stockExpanded,shown=expanded?all:all.slice(0,5),groups=new Map();
 for(const p of shown){if(!groups.has(p.category))groups.set(p.category,[]);groups.get(p.category).push(p);}
 const toggle=all.length>5?btn('brain-stock-toggle','<span>'+(expanded?'Recolher':'Mostrar Todos')+'</span>'+icon(expanded?'down':'chevron'),'brain-stock-toggle').replace('<button ','<button aria-expanded="'+expanded+'" '):'<span>Saldo atual</span>';
 return '<section class="brain-stock-diagnostic"><div class="brain-stock-heading"><h3>Estoque Geral</h3>'+toggle+'</div><p class="brain-stock-intro">Ainda restam: '+shown.length+' de '+all.length+' itens</p>'+[...groups].map(([category,products])=>'<div class="brain-stock-category"><h4>'+escape(category)+'</h4>'+products.map(p=>'<div class="brain-stock-line'+(p.stock<=0?' is-empty':'')+'"><div class="brain-stock-product"><span>'+escape(titleName(p.name))+'</span><small>'+escape(stockCardDescription(p))+'</small></div><strong>'+E.quantity(p.stock)+' '+E.unitLabel(p.unit,p.stock)+'</strong></div>').join('')+'</div>').join('')+(!all.length?'<p class="small muted">Nenhum produto cadastrado.</p>':'')+'</section>';
}

