// --- Leva 6: ordem dos produtos, pesos padrão, histórico da Loja, gráfico, CSV, estado da venda ---
// Ordem: dentro de cada área, do produto mais caro (por kg/L quando há peso) para o mais barato,
// e cada produto com suas apresentações em sequência de peso (250 g, 500 g, 1 kg).
function unitValue(p){const w=p.weight||p.volume||0;return w?p.price/(w/1000):p.price;}
function sortProducts(list){const cats=E.CATEGORIES,rank=new Map();list.forEach(p=>{const k=familyKey(p);rank.set(k,Math.max(rank.get(k)||0,unitValue(p)));});
 return list.slice().sort((a,b)=>{const ca=cats.indexOf(a.category),cb=cats.indexOf(b.category);if(ca!==cb)return (ca<0?99:ca)-(cb<0?99:cb);const ka=familyKey(a),kb=familyKey(b);if(ka!==kb)return rank.get(kb)-rank.get(ka)||ka.localeCompare(kb,'pt-BR');return (a.weight||a.volume||0)-(b.weight||b.volume||0)||a.price-b.price;});}
const baseProductList=productList;
productList=function(stockMode){return sortProducts(baseProductList(stockMode));};
// Pesos padrão no cadastro: três apresentações usuais por área (no café: 250 g, 500 g e 1 kg).
const WEIGHT_PRESETS={'Cafés':[250,500,1000],'Laticínios':[250,500,1000],'Charcutaria':[250,500,1000],'Doces':[250,500,1000],'Mel e apícolas':[250,500,1000],'Conservas e temperos':[100,250,500],'Grãos':[500,1000,5000],'Hortifruti-Granjeiro':[500,1000,2000],'Carnes e aves':[500,1000,2000],'Piscicultura':[500,1000,2000],'Panificação':[50,100,500],'Bolos':[500,1000,1500],'Beleza':[50,100,200],'Outros':[250,500,1000]};
const VOLUME_PRESETS={'Bebidas':[300,600,1000],'Laticínios':[200,500,1000]};
const baseDimensionOptions=dimensionOptions;
dimensionOptions=function(field,index){const all=baseDimensionOptions(field,index),presets=(field==='weight'?WEIGHT_PRESETS:field==='volume'?VOLUME_PRESETS:{})[productForm&&productForm.category];if(!presets)return all;const rest=all.filter(x=>!presets.some(p=>String(p)===String(x)));return [...presets,...rest];};

// Venda com vários produtos: estado de cada produto (ativo, com quantidade, pendente).
function draftGroupStates(){if(!draft)return [];const groups=[];draft.items.forEach((line,index)=>{const p=model.product(line.productId);if(!p)return;const key=familyKey(p);let g=groups.find(x=>x.key===key);if(!g){g={key,indices:[]};groups.push(g);}g.indices.push(index);});return groups.map(g=>({active:g.indices.includes(draft.active),done:g.indices.some(i=>E.number(draft.items[i].rawQty)>0)}));}

// Histórico da Loja (Vendas da semana) reorganizado: período claro, locais em linha, dias com total
// na mesma linha e cada venda com horário, pagamento, valor e itens um por linha.
function weekLabel(start,current){const diff=Math.round((Date.parse(current+'T12:00:00Z')-Date.parse(start+'T12:00:00Z'))/(7*864e5));return diff===0?'Esta semana':diff===1?'Semana passada':diff>1?'Há '+diff+' semanas':'Próxima semana';}
function weeklyPageClean(){const data=weekData(),fmt=(day,o)=>new Date(day+'T12:00:00Z').toLocaleDateString('pt-BR',o),weekEnd=shiftDay(weekStart,6),days=Array.from({length:7},(_,i)=>shiftDay(weekStart,i)),thisWeek=monday(E.dayKey(new Date()));
 const daily=day=>data.sales.filter(s=>E.dayKey(s.date)===day).sort((a,b)=>new Date(b.date)-new Date(a.date));
 const saleRow=s=>btn('sale-detail','<span class="hs-top"><span class="hs-time">'+new Date(s.date).toLocaleTimeString('pt-BR',{timeZone:'America/Sao_Paulo',hour:'2-digit',minute:'2-digit'})+' · '+escape(s.payments.map(p=>p.method).join(' + '))+(s.status==='returned'?' · <em>Devolvida</em>':'')+'</span><strong class="tabular">'+E.money(s.total)+'</strong></span><span class="hs-items">'+s.items.map(i=>'<span>'+E.quantity(i.qty)+'× '+escape(titleName(i.name))+'<small>'+escape(i.description)+'</small></span>').join('')+'</span>','hs-sale'+(s.status==='returned'?' is-returned':''),{id:s.id});
 const dayCard=day=>{const sales=daily(day),completed=sales.filter(s=>s.status==='completed'),total=completed.reduce((n,s)=>n+s.total,0),open=weekDaysOpen.has(day)||!!weekQuery;
  return '<section class="hs-day">'+btn('week-day','<span class="hs-day-name"><strong>'+escape(fmt(day,{weekday:'long'}))+'</strong><small>'+escape(fmt(day,{day:'numeric',month:'long'}))+' · '+grammarCount(completed.length,'venda','vendas')+'</small></span><span class="hs-day-total tabular">'+E.money(total)+'</span>'+icon(open?'down':'chevron'),'hs-day-head',{day})+(open?'<div class="hs-sales">'+(sales.length?sales.map(saleRow).join(''):'<p class="hs-empty">Nenhuma venda neste dia.</p>')+'</div>':'')+'</section>';};
 const withSales=days.filter(d=>daily(d).length).reverse(),empty=days.filter(d=>!daily(d).length);
 const head=header('Vendas','weekly-back').replace('<span class="spacer"></span>',btn('weekly-search',icon('search'),'title-search'));
 return '<div class="subview hs">'+head
 +'<div class="hs-period">'+btn('week-shift',icon('back'),'hs-arrow',{delta:-1})+'<span class="hs-range"><strong>'+escape(fmt(weekStart,{month:'short'})===fmt(weekEnd,{month:'short'})?fmt(weekStart,{day:'numeric'})+' – '+fmt(weekEnd,{day:'numeric',month:'short'}):fmt(weekStart,{day:'numeric',month:'short'})+' – '+fmt(weekEnd,{day:'numeric',month:'short'}))+'</strong><small>'+weekLabel(weekStart,thisWeek)+' · '+fmt(weekEnd,{year:'numeric'})+'</small></span>'+btn('week-shift',icon('chevron'),'hs-arrow',{delta:1})+'</div>'
 +'<div class="feira-chips hs-scopes" role="group" aria-label="Local">'+btn('week-scope','Loja','chip'+(scope==='loja'?' selected':''),{scope:'loja'})+model.data.events.map(e=>btn('week-scope',escape(e.name),'chip'+(scope===e.id?' selected':''),{scope:e.id})).join('')+'</div>'
 +(weekSearchOpen?'<label class="feira-search">'+icon('search')+'<input id="week-search" aria-label="Buscar venda" placeholder="Buscar produto, cliente ou pagamento" value="'+escape(weekQuery)+'"></label>':'')
 +'<section class="hs-summary"><small>'+escape(scopeName(scope))+' · semana</small><strong class="tabular">'+E.money(data.total)+'</strong><div class="hs-summary-stats"><span><b class="tabular">'+data.count+'</b> '+(data.count===1?'venda':'vendas')+'</span><span><b class="tabular">'+(data.count?E.money(Math.round(data.total/data.count)):'—')+'</b> por venda</span></div></section>'
 +(withSales.length?withSales.map(dayCard).join(''):'<p class="hs-empty hs-empty-week">Nenhuma venda nesta semana.</p>')
 +(empty.length&&withSales.length?'<p class="hs-empty-days">'+grammarCount(empty.length,'dia','dias')+' sem vendas: '+escape(empty.map(d=>fmt(d,{weekday:'short'}).replace('.','')).join(', '))+'</p>':'')
 +'</div>';}
const weeklyPageLegacy=weeklyPage;
weeklyPage=function(){return isFeira()?weeklyPageClean():weeklyPageLegacy();};
// Gestão no estilo Feira: o gráfico cronológico dá lugar ao ordenado.
const feiraHeroBase=feiraHero;
feiraHero=function(sel,m){const html=feiraHeroBase(sel,m),cut=html.indexOf('<section class="feira-chart"'),visible=!!model.data.settings.financialVisible;let hero=cut>=0?html.slice(0,cut):html,chart=feiraChartSorted(sel,m);
 // Valores escondidos: some o dinheiro (receita, ticket, resultado e valores das barras); a quantidade de vendas fica.
 if(!visible){hero=hero.replace(/R\$(&nbsp;|\s)?-?[\d.,]+/g,'••••••').replace('class="feira-hero-value"','class="feira-hero-value is-hidden"');chart=chart.replace(/<text[^>]*class="bar-value"[^>]*>[^<]*<\/text>/g,'');}
 const eye='<button type="button" data-action="toggle-financial" class="hero-eye" aria-label="'+(visible?'Ocultar':'Mostrar')+' valores" aria-pressed="'+visible+'">'+icon(visible?'eye':'eyeOff')+'</button>';
 hero=hero.replace(/<strong>([^<]+)<\/strong>/g,(tag,text)=>{const n=text.replace(/&nbsp;/g,' ').length;return n>=13?'<strong class="long xlong">'+text+'</strong>':n>=10?'<strong class="long">'+text+'</strong>':tag;}); // valores longos (ex.: R$ 1.234,56) diminuem para caber
 return hero.replace('<section class="feira-hero" aria-label="Resumo do período">',tag=>(m.result<0?tag.replace('class="feira-hero"','class="feira-hero is-negative"'):tag)+eye)+chart;};

// Gráfico: barras do menor para o maior, da esquerda para a direita, com o dia de cada uma.
function feiraChartSorted(sel,m){const entries=Object.entries(m.daily).filter(([day,v])=>v>0&&(!sel.month||day.slice(0,7)===sel.month)).sort((a,b)=>a[1]-b[1]);
 if(!entries.length)return '<section class="feira-chart"><h2>Receita por dia</h2><p class="feira-chart-empty">Sem vendas neste período.</p></section>';
 const max=entries[entries.length-1][1],W=320,H=150,n=entries.length,step=W/Math.max(n,4),bw=Math.min(36,step*0.62),x0=(W-step*n)/2;
 const bars=entries.map(([day,v],i)=>{const h=Math.max(4,v/max*(H-40)),x=x0+i*step+(step-bw)/2,y=H-22-h;return '<rect class="chart-bar" x="'+x.toFixed(1)+'" y="'+y.toFixed(1)+'" width="'+bw.toFixed(1)+'" height="'+h.toFixed(1)+'" rx="5"><title>'+dateBR(day)+': '+E.money(v)+'</title></rect>'+(n<=10?'<text x="'+(x+bw/2).toFixed(1)+'" y="'+(y-6).toFixed(1)+'" text-anchor="middle" class="bar-value">'+E.money(v).replace(/\s/g,' ').replace(',00','')+'</text>':'')+'<text x="'+(x+bw/2).toFixed(1)+'" y="'+H+'" text-anchor="middle">'+Number(day.slice(8))+'/'+day.slice(5,7)+'</text>';}).join('');
 return '<section class="feira-chart"><h2>Receita por dia</h2><p class="feira-chart-note">Do dia que menos vendeu para o que mais vendeu</p><svg viewBox="0 0 '+W+' '+H+'" role="img" aria-label="Receita por dia, do menor para o maior">'+bars+'</svg></section>';}

// CSV: planilha geral com tudo e uma planilha por evento.
function exportScoped(scopeId,name){const previous=dataScope;dataScope=scopeId;try{exportCSV(name,generalRows());}finally{dataScope=previous;}}
Object.assign(actions,{
 'export-everything':()=>exportScoped('all','agro-gestao-planilha-geral.csv'),
 'export-event':d=>{const e=model.data.events.find(x=>x.id===d.id);if(e)exportScoped(e.id,'evento-'+E.normalize(e.name).replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')+'-'+e.start+'.csv');}
});

// --- Aviso de feira: cartão com a data em destaque ---
const reminderBannerLegacy=reminderBanner;
reminderBanner=function(){const notices=eventReminders();if(!notices.length)return '';const r=notices[0],e=r.event,today=E.dayKey(Date.now()),days=Math.round((Date.parse(e.start+'T12:00:00Z')-Date.parse(today+'T12:00:00Z'))/864e5);
 const when=days<=0?'A feira é hoje':days===1?'A feira é amanhã':'Feira em '+days+' dias',parts=String(r.text).split(/[.!]\s+/).filter(Boolean),todo=(parts.length>1?parts.slice(1).join('. '):parts[0]).replace(/\.$/,'');
 const d=new Date(e.start+'T12:00:00Z'),month=d.toLocaleDateString('pt-BR',{month:'short',timeZone:'UTC'}).replace('.','');
 return '<section class="fair-card'+(days<=1?' is-soon':'')+'" role="status">'+btn('open-reminders','<span class="fc-date" aria-hidden="true"><b>'+d.getUTCDate()+'</b><small>'+escape(month)+'</small></span><span class="fc-text"><small>'+escape(when)+'</small><strong>'+escape(e.name)+'</strong><span>'+escape(todo)+'</span></span>'+icon('chevron'),'fc-main')+btn('reminder-dismiss',icon('close')+'<span class="sr-only">Dispensar aviso</span>','fc-close',{key:r.key})+'</section>';};

// --- Reposição rápida: até 4 produtos por vez, teclado próprio ---
let restock=null;
function openRestock(ids){ids=ids.filter(id=>model.product(id));if(!ids.length)return;restock={ids,page:0,values:{},active:ids[0]};paintRestock();}
function paintRestock(){const r=restock;if(!r)return;const pages=Math.ceil(r.ids.length/4),pageIds=r.ids.slice(r.page*4,r.page*4+4),last=r.page>=pages-1,active=model.product(r.active),decimal=active&&['kg','Litro'].includes(active.unit);
 const rows=pageIds.map(id=>{const p=model.product(id),on=id===r.active,value=r.values[id]||'';return btn('restock-pick','<span class="rr-name"><strong>'+escape(titleName(p.name))+'</strong><small>Agora: '+E.quantity(p.stock)+' '+escape(E.unitLabel(p.unit,p.stock))+'</small></span><span class="rr-value'+(value?'':' empty')+'"><span class="tabular">'+(value||'0')+'</span><small>'+escape(shortUnit(p.unit))+'</small></span>','restock-row'+(on?' active':''),{id});}).join('');
 const keys=[1,2,3,4,5,6,7,8,9].map(n=>btn('restock-digit',String(n),'restock-key',{digit:n})).join('')+(decimal?btn('restock-digit',',','restock-key',{digit:','}):'<span aria-hidden="true"></span>')+btn('restock-digit','0','restock-key',{digit:0})+btn('restock-erase',icon('backspace')+'<span>Corrigir</span>','restock-key restock-erase');
 openModal(r.ids.length===1?'Repor '+titleName(model.product(r.ids[0]).name):'Repor estoque',(r.ids.length>1?'<p class="dialog-text">Toque no produto e digite quanto entrou'+(pages>1?' · '+(r.page+1)+' de '+pages:'')+'.</p>':'<p class="dialog-text">Digite quanto entrou.</p>')+'<div class="restock-rows">'+rows+'</div><div class="restock-keypad" aria-label="Teclado de quantidade">'+keys+'</div>','restock',null,(last?'':btn('restock-next','Próximos','primary modal-action'))+btn('restock-finish','Finalizar','success modal-action'));}
function finishRestock(){const r=restock;if(!r)return;let done=0;const missing=[],failed=[];
 for(const id of r.ids){const p=model.product(id),raw=r.values[id];if(!raw||!(E.number(raw)>0)){missing.push(titleName(p.name));continue;}try{model.move(id,'add',raw,'Reposição');done++;}catch(e){failed.push(titleName(p.name));}}
 restock=null;if(done&&!persist()){closeModal();return toast('Não foi possível salvar a reposição. Libere espaço.');}closeModal();render();
 const list=n=>n.length>2?n.slice(0,2).join(', ')+' e mais '+(n.length-2):n.join(' e ');
 if(!done)toast('Estoque não renovado'+(missing.length?': '+list(missing):'')+'.');
 else if(missing.length||failed.length)toast('Estoque não renovado: '+list([...missing,...failed])+'. Os demais foram atualizados.');
 else toast('Estoque renovado: '+grammarCount(done,'produto','produtos')+'.');}
function stockLevels(){return model.data.products.map(p=>{const r=stockRatio(p);return{id:p.id,name:titleName(p.name),detail:weightLabel(p),stock:p.stock,unit:E.unitLabel(p.unit,p.stock),ratio:r.reference>0?r.ratio:null};});}

// --- Zerar dados para testes ---
let testReset={sales:true,stock:true,intel:true};
function testResetModal(){const row=(key,label,note)=>'<button type="button" data-action="test-reset-toggle" data-key="'+key+'" class="client-row" role="switch" aria-checked="'+testReset[key]+'"><span>'+label+'<small class="settings-note" style="display:block;margin:2px 0 0">'+note+'</small></span><span class="switch'+(testReset[key]?' on':'')+'"><i></i></span></button>';
 openModal('Dados para testes','<p class="dialog-text">Zere o que quiser testar de novo. Produtos, clientes, eventos e ajustes continuam. Ou volte tudo aos dados de exemplo.</p>'+row('sales','Vendas e despesas','Vendas, devoluções, leituras de QR e despesas.')+row('stock','Estoque','Quantidades vão a zero e o histórico de movimentos é apagado.')+row('intel','Inteligência','Abordagens registradas, análises e lembretes.'),'test-reset',null,btn('test-reset-confirm','Zerar agora','danger modal-action',null,!Object.values(testReset).some(Boolean))+btn('reset-confirm','Restaurar dados de exemplo','link-row')+btn('close-modal','Cancelar','link-row'));}
function applyTestReset(){const d=model.data;if(testReset.sales){d.sales=[];d.expenses=[];draft=null;pendingCheckout=null;recipientPending=null;}if(testReset.stock){d.products.forEach(p=>p.stock=0);d.movements=[];d.eventLoads=[];}if(testReset.intel){d.contacts=[];delete d.settings.backupReminderAskedAt;aiResult='';aiResultSource='';aiResultStamp='';}
 if(!persist())return toast('Não foi possível salvar. Libere espaço.');closeModal();page='Vender';render();toast('Dados de teste zerados.');}

Object.assign(actions,{
 'feira-filter':d=>{filter=d.value;render();},
 'feira-restock':d=>{const g=stockGroups()[d.group]||[];openRestock(g.map(p=>p.id));},
 'restock-pick':d=>{if(!restock)return;restock.active=d.id;paintRestock();},
 'restock-digit':d=>{if(!restock)return;const id=restock.active,cur=restock.values[id]||'',digit=String(d.digit);if(digit===','&&cur.includes(','))return;if(cur.replace(',','').length>=6)return;restock.values[id]=(cur==='0'&&digit!==','?'':cur)+(digit===','&&!cur?'0':'')+digit;paintRestock();},
 'restock-erase':()=>{if(!restock)return;const id=restock.active;restock.values[id]=(restock.values[id]||'').slice(0,-1);paintRestock();},
 'restock-next':()=>{if(!restock)return;restock.page++;restock.active=restock.ids[restock.page*4];paintRestock();},
 'restock-finish':()=>finishRestock(),
 'test-reset':()=>testResetModal(),
 'test-reset-toggle':d=>{testReset[d.key]=!testReset[d.key];testResetModal();},
 'test-reset-confirm':()=>applyTestReset()
});

// --- Orientação (src/features/advisor): o motor recebe só os números reais do app ---
function advisorName(p){const same=model.data.products.filter(x=>E.normalize(x.name)===E.normalize(p.name)).length;return titleName(p.name)+(same>1&&weightLabel(p)?' '+weightLabel(p):'');}
function advisorPeriod(sel){const month=sel.month?new Date(sel.month+'-15T12:00:00Z').toLocaleDateString('pt-BR',{month:'long',year:'numeric'}):'Todo o período';return month.charAt(0).toUpperCase()+month.slice(1)+(sel.days&&sel.days.length?' · '+grammarCount(sel.days.length,'dia','dias'):'')+(sel.scope&&sel.scope!=='all'?' · '+reportScopeName(sel.scope):'');}
function advisorSummary(sel){const m=filteredMetrics(sel),completed=model.data.sales.filter(s=>s.status==='completed'),start=sel.month?Date.parse(sel.month+'-01T00:00:00-03:00'):Date.now(),first=new Map(),count=new Map();
 completed.forEach(s=>{if(!s.customerId)return;const t=Date.parse(s.date);if(!first.has(s.customerId)||t<first.get(s.customerId))first.set(s.customerId,t);count.set(s.customerId,(count.get(s.customerId)||0)+1);});
 const clients=[...new Set(m.sales.map(s=>s.customerId).filter(Boolean))],returning=clients.filter(id=>first.get(id)<start).length,names=new Map(model.data.products.map(p=>[p.id,advisorName(p)]));
 return{revenue:m.revenue,cost:m.cost,expense:m.expense,result:m.result,salesCount:m.sales.length,ticket:Math.round(m.ticket),productsPerSale:m.sales.length?m.sales.reduce((n,s)=>n+new Set(s.items.map(i=>i.productId)).size,0)/m.sales.length:0,
  rank:m.rank.map(r=>({id:r.id,name:names.get(r.id)||titleName(r.name),qty:r.qty,amount:r.amount})),identified:m.sales.filter(s=>s.customerId).length,clients:clients.length,returning,newClients:clients.length-returning,
  marketing:model.data.expenses.filter(x=>x.category==='Marketing'&&matchesSelection(x,sel)).reduce((n,x)=>n+x.amount,0),purchasesPerClient:clients.length?clients.reduce((n,id)=>n+(count.get(id)||0),0)/clients.length:0,
  qrShown:m.sales.filter(s=>s.qrPayload).length,qrRead:m.sales.filter(s=>s.qrReadAt).length};}
function advisorInput(){const sel=selection(),prev=previousSelection(sel),today=E.dayKey(Date.now()),names=new Map(model.data.products.map(p=>[p.id,advisorName(p)]));
 const finished=model.data.events.filter(e=>(sel.scope===e.id||['all','events'].includes(sel.scope))&&eventLoad(e.id)&&(e.status==='finished'||e.end<today)&&(!sel.month||e.start.slice(0,7)===sel.month||e.end.slice(0,7)===sel.month));
 const events=finished.map(e=>{const b=eventLoadBalance(e.id);return{id:e.id,name:e.name,items:b.load.items.map(i=>{const p=model.product(i.productId),rest=b.balance.find(x=>x.productId===i.productId&&x.unit===i.unit);return{productId:i.productId,name:names.get(i.productId)||titleName(i.name||'Produto'),taken:i.qty,left:Math.max(0,rest?rest.qty:0),price:p?p.price:0};})};});
 const next=model.data.events.filter(e=>e.status==='active'&&e.start>=today).sort((a,b)=>a.start.localeCompare(b.start))[0];
 return{periodLabel:advisorPeriod(sel),previousLabel:advisorPeriod(prev),hasCost:model.data.products.some(p=>p.cost>0),portfolioPublished:!!(model.data.portfolio&&model.data.portfolio.publishedAt),
  products:model.data.products.map(p=>({id:p.id,name:names.get(p.id),price:p.price,cost:p.cost,stock:p.stock,min:p.min,unitLabel:E.unitLabel(p.unit,p.stock)})),
  current:advisorSummary(sel),previous:prev.noDays?null:advisorSummary(prev),events,
  upcoming:next?{name:next.name,daysUntil:Math.round((Date.parse(next.start+'T12:00:00-03:00')-Date.parse(today+'T12:00:00-03:00'))/864e5)}:null};}
function advisorPanel(){const a=window.TerritorioAdvisor;if(!a)return '';try{return a.panel(advisorInput());}catch(e){console.error('Orientação indisponível',e);return '';}}
// A Inteligência sem IA conectada responde com a mesma orientação; com IA, ela recebe a orientação e o método do material.
localAnalysis=function(){const a=window.TerritorioAdvisor,q=document.getElementById('ai-question');return a?a.answer(q?q.value:'',advisorInput()):'';};
const advisorBaseContext=analysisContext;
analysisContext=function(){const ctx=advisorBaseContext(),a=window.TerritorioAdvisor;if(a){try{ctx.orientation=a.summary(advisorInput());ctx.responseGuide=a.aiGuide;}catch(e){}}return ctx;};
